COURSE.add({
  id: 'm11', order: 11, icon: '📊',
  title: { en: 'Evaluations: proving your AI is good', he: 'Evaluations: להוכיח שה-AI שלך טוב' },
  summary: { en: 'How to measure a GenAI app with numbers instead of feelings: datasets, metrics, LLM-as-a-judge, Bedrock evaluation jobs and AgentCore Evaluations.', he: 'איך מודדים אפליקציית GenAI עם מספרים במקום תחושות: datasets, מטריקות, LLM-as-a-judge, ‏evaluation jobs של Bedrock ו-AgentCore Evaluations.' },
  glossary: [
    { term: 'Evaluation', aka: ['evaluations', 'eval', 'evals'], en: 'Running your app on many prepared inputs and scoring the outputs, to get a number that says how good it is.', he: 'הרצת האפליקציה על הרבה קלטים מוכנים ומתן ציון לפלטים, כדי לקבל מספר שאומר כמה היא טובה.' },
    { term: 'Golden dataset', aka: ['golden set', 'evaluation dataset', 'prompt dataset'], en: 'A fixed, hand-checked list of test questions (often with the expected answers) that you run again after every change.', he: 'רשימה קבועה ובדוקה ידנית של שאלות בדיקה (לרוב עם התשובות המצופות) שמריצים שוב אחרי כל שינוי.' },
    { term: 'Ground truth', aka: ['reference response', 'referenceResponse', 'reference answer'], en: 'The answer that a human decided is correct for a test question. The model answer is compared with it.', he: 'התשובה שאדם קבע שהיא הנכונה לשאלת בדיקה. משווים אליה את תשובת המודל.' },
    { term: 'Metric', aka: ['metrics'], en: 'One named way to score an answer, such as correctness or faithfulness. Each metric answers one question about quality.', he: 'דרך אחת עם שם לתת ציון לתשובה, כמו correctness או faithfulness. כל מטריקה עונה על שאלה אחת לגבי איכות.' },
    { term: 'Offline evaluation', en: 'Evaluation on a prepared dataset before release. Nothing reaches real users.', he: 'Evaluation על dataset מוכן לפני שחרור. שום דבר לא מגיע למשתמשים אמיתיים.' },
    { term: 'Online evaluation', en: 'Continuous scoring of a sample of real production traffic.', he: 'מתן ציונים רציף לדגימה של תעבורת פרודקשן אמיתית.' },
    { term: 'Regression', aka: ['regressions'], en: 'Something that worked before and got worse after a change.', he: 'משהו שעבד קודם והורע אחרי שינוי.' },
    { term: 'Baseline', en: 'The scores of the current version. Every new version is compared with it.', he: 'הציונים של הגרסה הנוכחית. כל גרסה חדשה מושווית אליהם.' },
    { term: 'LLM-as-a-judge', aka: ['model as a judge', 'judge model', 'evaluator model', 'judge'], en: 'Using a second model to read each answer and give it a score with an explanation, following instructions you wrote.', he: 'שימוש במודל שני שקורא כל תשובה ונותן לה ציון עם הסבר, לפי הוראות שכתבת.' },
    { term: 'Generator model', aka: ['generator'], en: 'The model that writes the answers being evaluated. The judge model scores them.', he: 'המודל שכותב את התשובות שנבדקות. ה-judge model נותן להן ציון.' },
    { term: 'Human evaluation', aka: ['human-based evaluation'], en: 'People read the answers and rate them. Slow and expensive, but it is the reference for everything else.', he: 'אנשים קוראים את התשובות ומדרגים אותן. איטי ויקר, אבל זו נקודת הייחוס לכל השאר.' },
    { term: 'Programmatic evaluation', aka: ['automatic evaluation', 'algorithmic metric'], en: 'Scoring by a fixed algorithm (for example word overlap with the reference), with no judge model.', he: 'מתן ציון על ידי אלגוריתם קבוע (למשל חפיפת מילים עם תשובת הייחוס), בלי judge model.' },
    { term: 'Correctness', en: 'Is the answer factually right? Compared with the ground truth when you have one.', he: 'האם התשובה נכונה עובדתית? משווים ל-ground truth כשיש.' },
    { term: 'Completeness', en: 'Does the answer cover every part of the question?', he: 'האם התשובה מכסה כל חלק של השאלה?' },
    { term: 'Faithfulness', aka: ['groundedness'], en: 'Does the answer say only things that the given context supports? Low faithfulness means hallucination.', he: 'האם התשובה אומרת רק דברים שההקשר שניתן תומך בהם? faithfulness נמוך פירושו hallucination.' },
    { term: 'Helpfulness', en: 'Does the answer actually help the user reach their goal?', he: 'האם התשובה באמת עוזרת למשתמש להגיע למטרה שלו?' },
    { term: 'Relevance', aka: ['answer relevance', 'response relevance'], en: 'Does the answer address the question that was asked?', he: 'האם התשובה מתייחסת לשאלה שנשאלה?' },
    { term: 'Context relevance', en: 'A retrieval metric: are the retrieved chunks about the question?', he: 'מטריקת אחזור: האם ה-chunks שאוחזרו עוסקים בשאלה?' },
    { term: 'Context coverage', en: 'A retrieval metric: do the retrieved chunks contain everything needed for the reference answer? Needs ground truth.', he: 'מטריקת אחזור: האם ה-chunks שאוחזרו מכילים את כל מה שנדרש לתשובת הייחוס? דורש ground truth.' },
    { term: 'Citation precision', aka: ['citation coverage'], en: 'RAG metrics about citations: are the cited passages really relevant (precision), and is the answer backed by citations (coverage)?', he: 'מטריקות RAG על ציטוטים: האם הקטעים שצוטטו באמת רלוונטיים (precision), והאם התשובה מגובה בציטוטים (coverage)?' },
    { term: 'Robustness', en: 'Does the answer stay the same when the prompt changes in small, meaningless ways such as typos?', he: 'האם התשובה נשארת זהה כשהפרומפט משתנה בדרכים קטנות וחסרות משמעות כמו שגיאות הקלדה?' },
    { term: 'Toxicity', aka: ['harmfulness'], en: 'Does the answer contain harmful or offensive content?', he: 'האם התשובה מכילה תוכן מזיק או פוגעני?' },
    { term: 'Evaluation job', aka: ['CreateEvaluationJob'], en: 'A Bedrock batch job that runs a dataset through a model or a RAG system, scores the answers and writes a report.', he: 'job אצוותי של Bedrock שמריץ dataset דרך מודל או מערכת RAG, נותן ציון לתשובות וכותב דוח.' },
    { term: 'JSONL', aka: ['JSON Lines'], en: 'A text file where every line is one complete JSON object. The usual format for datasets.', he: 'קובץ טקסט שבו כל שורה היא אובייקט JSON שלם אחד. הפורמט הרגיל ל-datasets.' },
    { term: 'Bring your own inference', aka: ['BYOI', 'Bring your own inference responses'], en: 'You give the evaluation job answers that were already produced elsewhere, so it only has to score them.', he: 'נותנים ל-evaluation job תשובות שכבר נוצרו במקום אחר, כך שהוא רק צריך לתת להן ציון.' },
    { term: 'Custom metric', aka: ['custom metrics', 'custom evaluator'], en: 'A metric you define yourself: your own judge prompt and rating scale, for a quality that the built-in metrics do not cover.', he: 'מטריקה שמגדירים לבד: פרומפט judge וסולם דירוג משלך, לאיכות שהמטריקות המובנות לא מכסות.' },
    { term: 'Rating scale', aka: ['rubric'], en: 'The list of possible scores and what each one means, given to the judge so it scores the same way every time.', he: 'רשימת הציונים האפשריים ומה כל אחד אומר, שניתנת ל-judge כדי שייתן ציון באותה צורה בכל פעם.' },
    { term: 'Evaluator', aka: ['evaluators', 'built-in evaluator'], en: 'In AgentCore Evaluations: one scoring unit, such as Builtin.Helpfulness. It is what Bedrock calls a metric, packaged with its prompt and judge model.', he: 'ב-AgentCore Evaluations: יחידת ציון אחת, כמו Builtin.Helpfulness. זה מה ש-Bedrock קורא לו metric, ארוז עם הפרומפט וה-judge model שלו.' },
    { term: 'Session', aka: ['sessions'], en: 'One whole conversation between a user and an agent. It contains traces.', he: 'שיחה שלמה אחת בין משתמש לסוכן. היא מכילה traces.' },
    { term: 'Trace', aka: ['traces'], en: 'The record of one request (one turn) through the agent. It contains spans.', he: 'התיעוד של בקשה אחת (תור אחד) דרך הסוכן. הוא מכיל spans.' },
    { term: 'Span', aka: ['spans'], en: 'One step inside a trace: a model call or a tool call.', he: 'צעד אחד בתוך trace: קריאה למודל או קריאה לכלי.' },
    { term: 'Goal success rate', en: 'An agent metric at session level: did the user get what they came for by the end of the conversation?', he: 'מטריקת סוכן ברמת הסשן: האם המשתמש קיבל את מה שבא בשבילו עד סוף השיחה?' },
    { term: 'Tool selection accuracy', aka: ['tool parameter accuracy'], en: 'Agent metrics at tool level: did the agent pick the right tool (selection) and fill in the right arguments (parameter)?', he: 'מטריקות סוכן ברמת הכלי: האם הסוכן בחר את הכלי הנכון (selection) ומילא את הארגומנטים הנכונים (parameter)?' },
    { term: 'Sampling rate', aka: ['sampling'], en: 'The share of production sessions that online evaluation scores. 10% means one session in ten.', he: 'החלק מסשני הפרודקשן ש-online evaluation נותן להם ציון. 10% פירושו סשן אחד מכל עשרה.' },
    { term: 'On-demand evaluation', en: 'You send specific traces or spans to be scored right now and get the scores back at once.', he: 'שולחים traces או spans מסוימים לקבלת ציון עכשיו ומקבלים את הציונים מיד.' },
    { term: 'Batch evaluation', en: 'An asynchronous job that scores many recorded sessions at once, with optional ground truth.', he: 'job אסינכרוני שנותן ציון להרבה סשנים מוקלטים בבת אחת, עם ground truth אופציונלי.' },
    { term: 'A/B test', aka: ['A/B testing'], en: 'Sending part of the real traffic to a new variant and comparing its results with the current one.', he: 'שליחת חלק מהתעבורה האמיתית לגרסה חדשה והשוואת התוצאות שלה לגרסה הנוכחית.' },
    { term: 'CI', aka: ['continuous integration'], en: 'The automatic pipeline that builds and tests every code change before it is merged.', he: 'ה-pipeline האוטומטי שבונה ובודק כל שינוי בקוד לפני שהוא ממוזג.' }
  ],
  lessons: [
    {
      id: 'm11l1', minutes: 12,
      title: { en: 'Why GenAI needs evaluation', he: 'למה GenAI צריך evaluation' },
      blocks: [
        { t: 'p', en: 'You change one line in the system prompt. You try three questions. The answers look fine. You ship. Two days later support tells you that the bot stopped mentioning the refund deadline. Nobody saw it, because nobody asked that question before shipping.', he: 'אתה משנה שורה אחת ב-system prompt. אתה מנסה שלוש שאלות. התשובות נראות בסדר. אתה משחרר. יומיים אחר כך התמיכה מספרת לך שהבוט הפסיק להזכיר את המועד האחרון להחזר. אף אחד לא ראה את זה, כי אף אחד לא שאל את השאלה הזו לפני השחרור.' },
        { t: 'p', en: 'This is the normal way GenAI projects fail. "Looks fine" is not a test. A model is [[Non-deterministic]], an answer can be wrong in a hundred different ways, and every change (prompt, model, chunking, a tool description) moves quality somewhere you are not looking. An [[Evaluation]] replaces the feeling with a number.', he: 'כך בדרך כלל פרויקטים של GenAI נכשלים. "נראה בסדר" זה לא בדיקה. מודל הוא [[Non-deterministic]], תשובה יכולה להיות שגויה במאה דרכים שונות, וכל שינוי (פרומפט, מודל, chunking, תיאור של כלי) מזיז את האיכות במקום שאתה לא מסתכל עליו. [[Evaluation]] מחליף את התחושה במספר.' },
        { t: 'table', head: { en: ['', 'Unit test', 'Evaluation'], he: ['', 'Unit test', 'Evaluation'] }, rows: {
          en: [['Checks', 'Code', 'Behaviour of a model, a RAG system or an agent'], ['Expected result', 'One exact value', 'Many acceptable answers'], ['Result', 'Pass or fail', 'A score, usually an average over many examples'], ['Same input twice', 'Same result', 'Can differ'], ['A failure means', 'A bug', 'Maybe a bug, maybe noise. You look at the trend and at examples']],
          he: [['בודק', 'קוד', 'התנהגות של מודל, מערכת RAG או סוכן'], ['התוצאה המצופה', 'ערך מדויק אחד', 'הרבה תשובות קבילות'], ['התוצאה', 'עבר או נכשל', 'ציון, בדרך כלל ממוצע על הרבה דוגמאות'], ['אותו קלט פעמיים', 'אותה תוצאה', 'יכול להיות שונה'], ['כישלון אומר', 'באג', 'אולי באג, אולי רעש. מסתכלים על המגמה ועל דוגמאות']] } },
        { t: 'note', kind: 'tip', en: 'You still need unit tests for your code: parsing, tool functions, retries. Evaluations come **on top**, for the part that a unit test cannot check: is the answer good?', he: 'עדיין צריך unit tests לקוד שלך: parsing, פונקציות של כלים, retries. Evaluations באים **בנוסף**, לחלק ש-unit test לא יכול לבדוק: האם התשובה טובה?' },
        { t: 'h', en: 'The vocabulary', he: 'אוצר המילים' },
        { t: 'list', en: [
          '**[[Golden dataset]]**: your fixed list of test questions, checked by a human. You run all of it after every change.',
          '**[[Ground truth]]**: the correct answer for a test question, written or approved by a human. AWS calls it the reference response.',
          '**[[Metric]]**: one named score, such as [[Correctness]] or [[Faithfulness]].',
          '**[[Baseline]]**: the scores of what is in production now. A new version must not be worse.',
          '**[[Regression]]**: a score that dropped after a change.',
          '**[[Offline evaluation]]**: on the golden dataset, before release. **[[Online evaluation]]**: on a sample of real traffic, after release.'
        ], he: [
          '**[[Golden dataset]]**: הרשימה הקבועה שלך של שאלות בדיקה, שנבדקה על ידי אדם. מריצים את כולה אחרי כל שינוי.',
          '**[[Ground truth]]**: התשובה הנכונה לשאלת בדיקה, שאדם כתב או אישר. AWS קוראת לזה reference response.',
          '**[[Metric]]**: ציון אחד עם שם, כמו [[Correctness]] או [[Faithfulness]].',
          '**[[Baseline]]**: הציונים של מה שנמצא עכשיו בפרודקשן. גרסה חדשה לא יכולה להיות גרועה יותר.',
          '**[[Regression]]**: ציון שירד אחרי שינוי.',
          '**[[Offline evaluation]]**: על ה-golden dataset, לפני שחרור. **[[Online evaluation]]**: על דגימה של תעבורה אמיתית, אחרי שחרור.'
        ] },
        { t: 'flow', steps: { en: ['Golden dataset (questions + reference answers)', 'Run the app on every question', 'Score every answer with each metric', 'Average the scores', 'Compare with the baseline', 'Ship, or fix and run again'], he: ['Golden dataset (שאלות + תשובות ייחוס)', 'מריצים את האפליקציה על כל שאלה', 'נותנים ציון לכל תשובה בכל מטריקה', 'ממצעים את הציונים', 'משווים ל-baseline', 'משחררים, או מתקנים ומריצים שוב'] }, caption: { en: 'One evaluation run.', he: 'ריצת evaluation אחת.' } },
        { t: 'quiz', q: { en: 'Your team says: "We tested the new prompt on 5 questions and all 5 answers were good." What is the main problem with this as evidence?', he: 'הצוות שלך אומר: "בדקנו את הפרומפט החדש על 5 שאלות וכל 5 התשובות היו טובות." מה הבעיה העיקרית עם זה כראיה?' },
          options: { en: ['Five is an odd number', 'The questions were picked on the spot, cover little, and nobody compared with the old prompt on the same questions', 'Prompts cannot be tested', 'The temperature was not 0'], he: ['חמש הוא מספר אי-זוגי', 'השאלות נבחרו במקום, מכסות מעט, ואף אחד לא השווה לפרומפט הישן על אותן שאלות', 'אי אפשר לבדוק פרומפטים', 'ה-temperature לא הייתה 0'] },
          answer: 1, explain: { en: 'Evidence needs a fixed dataset that covers the important cases, and a comparison with a baseline. Five hand-picked questions show that the prompt can work, not that nothing broke.', he: 'ראיה דורשת dataset קבוע שמכסה את המקרים החשובים, והשוואה ל-baseline. חמש שאלות שנבחרו ידנית מראות שהפרומפט יכול לעבוד, לא ששום דבר לא נשבר.' } },
        { t: 'h', en: 'Who gives the score? Three options', he: 'מי נותן את הציון? שלוש אפשרויות' },
        { t: 'table', head: { en: ['Scorer', 'How', 'Good', 'Bad'], he: ['מי נותן ציון', 'איך', 'טוב', 'רע'] }, rows: {
          en: [
            ['**Code** ([[Programmatic evaluation]])', 'An algorithm compares the answer with the reference: exact match, word overlap, similarity of meaning.', 'Cheap, fast, repeatable.', 'Needs a reference answer. Punishes a correct answer that uses different words.'],
            ['**A model** ([[LLM-as-a-judge]])', 'A second model reads the question, the answer (and the context or the reference) and gives a score with an explanation.', 'Understands meaning. Scales to thousands of answers.', 'Costs tokens. The judge can be wrong or biased, so you must check it.'],
            ['**People** ([[Human evaluation]])', 'Reviewers rate answers with thumbs or a scale.', 'The most trusted. Finds problems you did not think to measure.', 'Slow and expensive. People disagree with each other.']
          ],
          he: [
            ['**קוד** ([[Programmatic evaluation]])', 'אלגוריתם משווה את התשובה לתשובת הייחוס: התאמה מדויקת, חפיפת מילים, דמיון משמעות.', 'זול, מהיר, חוזר על עצמו.', 'דורש תשובת ייחוס. מעניש תשובה נכונה שמשתמשת במילים אחרות.'],
            ['**מודל** ([[LLM-as-a-judge]])', 'מודל שני קורא את השאלה, את התשובה (ואת ההקשר או תשובת הייחוס) ונותן ציון עם הסבר.', 'מבין משמעות. מתאים לאלפי תשובות.', 'עולה טוקנים. ה-judge יכול לטעות או להיות מוטה, אז חייבים לבדוק אותו.'],
            ['**אנשים** ([[Human evaluation]])', 'בודקים מדרגים תשובות עם אגודל או סולם.', 'הכי אמין. מוצא בעיות שלא חשבת למדוד.', 'איטי ויקר. אנשים לא מסכימים זה עם זה.']
          ] } },
        { t: 'p', en: 'In practice you mix them. People build the golden dataset and check a small sample. A judge model scores everything, every day. Code checks the things that have one right answer (did the agent call the right tool? is the JSON valid?).', he: 'בפועל משלבים. אנשים בונים את ה-golden dataset ובודקים דגימה קטנה. Judge model נותן ציון לכל דבר, כל יום. קוד בודק את הדברים שיש להם תשובה נכונה אחת (האם הסוכן קרא לכלי הנכון? האם ה-JSON תקין?).' },
        { t: 'sim', id: 'judge', title: { en: 'Be the judge', he: 'היה אתה ה-judge' }, intro: { en: 'Four cases. For each one read the question, the context and the answer, and decide what is wrong with the answer, if anything. This is exactly what a judge model does, thousands of times.', he: 'ארבעה מקרים. בכל אחד קרא את השאלה, את ההקשר ואת התשובה, והחלט מה לא בסדר בתשובה, אם בכלל. זה בדיוק מה ש-judge model עושה, אלפי פעמים.' } },
        { t: 'note', kind: 'jargon', en: 'Notice what you just did: you gave a **different verdict for a different kind of failure**. "Not faithful", "incomplete" and "not relevant" are three separate metrics. One number called "quality" would hide which one broke, and each one has a different fix.', he: 'שים לב מה עשית עכשיו: נתת **פסק דין שונה לסוג כישלון שונה**. "לא נאמנה", "לא שלמה" ו"לא רלוונטית" הן שלוש מטריקות נפרדות. מספר אחד בשם "איכות" היה מסתיר איזו מהן נשברה, ולכל אחת יש תיקון אחר.' },
        { t: 'quiz', q: { en: 'You want to check 2,000 answers every night for "does the answer stay within the provided documents". Which scorer fits best?', he: 'אתה רוצה לבדוק 2,000 תשובות כל לילה לגבי "האם התשובה נשארת בתוך המסמכים שסופקו". איזה נותן ציון הכי מתאים?' },
          options: { en: ['Exact string match with the reference', 'Three human reviewers', 'A unit test with assertEqual', 'An LLM judge with a faithfulness metric'], he: ['התאמת מחרוזת מדויקת לתשובת הייחוס', 'שלושה בודקים אנושיים', 'Unit test עם assertEqual', 'LLM judge עם מטריקת faithfulness'] },
          answer: 3, explain: { en: 'The check needs understanding of meaning, at a volume that people cannot handle every night. Exact match fails on every answer that is right but worded differently.', he: 'הבדיקה דורשת הבנת משמעות, בנפח שאנשים לא יכולים לטפל בו כל לילה. התאמה מדויקת נכשלת על כל תשובה שנכונה אבל מנוסחת אחרת.' } },
        { t: 'match', prompt: { en: 'Match the word to its meaning.', he: 'התאם את המילה למשמעות שלה.' }, pairs: [
          { a: 'Golden dataset', b: { en: 'The fixed test questions you rerun after every change', he: 'שאלות הבדיקה הקבועות שמריצים שוב אחרי כל שינוי' } },
          { a: 'Ground truth', b: { en: 'The human-approved correct answer', he: 'התשובה הנכונה שאדם אישר' } },
          { a: 'Baseline', b: { en: 'The scores of the version in production now', he: 'הציונים של הגרסה שנמצאת עכשיו בפרודקשן' } },
          { a: 'Regression', b: { en: 'It was good, and after the change it is worse', he: 'זה היה טוב, ואחרי השינוי זה גרוע יותר' } },
          { a: 'Online evaluation', b: { en: 'Scoring a sample of real traffic', he: 'מתן ציון לדגימה של תעבורה אמיתית' } }
        ] },
        { t: 'quiz', q: { en: 'Which of these does offline evaluation NOT give you?', he: 'מה מהבאים offline evaluation לא נותן לך?' },
          options: { en: ['Knowledge of the questions real users ask that you never thought of', 'A comparison of two prompts on the same questions', 'A safe test before release', 'A repeatable score'], he: ['ידיעה על שאלות שמשתמשים אמיתיים שואלים ושלא חשבת עליהן', 'השוואה של שני פרומפטים על אותן שאלות', 'בדיקה בטוחה לפני שחרור', 'ציון שאפשר לחזור עליו'] },
          answer: 0, explain: { en: 'A golden dataset contains only what you put in it. Real users surprise you. That is why you also need online evaluation, and why the failures it finds should go back into the golden dataset.', he: 'Golden dataset מכיל רק מה ששמת בו. משתמשים אמיתיים מפתיעים. לכן צריך גם online evaluation, ולכן הכישלונות שהוא מוצא צריכים לחזור ל-golden dataset.' } },
        { t: 'reveal', q: { en: 'A product manager asks: "Why do we need evaluations? We have QA." Answer in a few sentences.', he: 'מנהל מוצר שואל: "למה אנחנו צריכים evaluations? יש לנו QA." ענה בכמה משפטים.' },
          a: { en: 'QA checks that the software works: buttons, flows, errors. It cannot tell us whether 2,000 different answers are correct, complete and grounded, and it cannot repeat that check after every prompt or model change. An evaluation is an automatic, repeatable quality measurement on a fixed set of questions, plus a sample of live traffic. It tells us with a number whether a change made the product better or worse, before the customers tell us.', he: 'QA בודק שהתוכנה עובדת: כפתורים, תהליכים, שגיאות. הוא לא יכול להגיד לנו אם 2,000 תשובות שונות נכונות, שלמות ומבוססות, והוא לא יכול לחזור על הבדיקה הזו אחרי כל שינוי בפרומפט או במודל. Evaluation הוא מדידת איכות אוטומטית שאפשר לחזור עליה, על סט קבוע של שאלות ועוד דגימה של תעבורה חיה. הוא אומר לנו עם מספר אם שינוי שיפר או הרע את המוצר, לפני שהלקוחות אומרים לנו.' } }
      ]
    },
    {
      id: 'm11l2', minutes: 13,
      title: { en: 'Metrics that matter', he: 'מטריקות שחשובות' },
      blocks: [
        { t: 'p', en: 'A [[Metric]] is one question about quality. Below are the metrics you will meet in AWS, with the exact names AWS uses. Do not learn them as a list. Learn **which question each one answers**, because that tells you what to fix.', he: '[[Metric]] היא שאלה אחת על איכות. למטה המטריקות שתפגוש ב-AWS, עם השמות המדויקים ש-AWS משתמשת בהם. אל תלמד אותן כרשימה. למד **על איזו שאלה כל אחת עונה**, כי זה אומר לך מה לתקן.' },
        { t: 'h', en: 'Metrics for an answer', he: 'מטריקות לתשובה' },
        { t: 'p', en: 'Example for all rows. Question: "What is the refund window and how do I ask for one?" Context: "Refunds are available within 30 days. Open a ticket in the support portal."', he: 'דוגמה לכל השורות. שאלה: "What is the refund window and how do I ask for one?" הקשר: "Refunds are available within 30 days. Open a ticket in the support portal."' },
        { t: 'table', head: { en: ['Metric', 'The question it answers', 'An answer that scores low'], he: ['מטריקה', 'השאלה שהיא עונה עליה', 'תשובה שמקבלת ציון נמוך'] }, rows: {
          en: [
            ['[[Correctness]]', 'Is it factually right?', '"You have 60 days."'],
            ['[[Completeness]]', 'Does it cover every part of the question?', '"You have 30 days." (how to ask is missing)'],
            ['[[Faithfulness]]', 'Does it say only what the context supports?', '"30 days, and we refund within 24 hours." (the second part is invented)'],
            ['[[Helpfulness]]', 'Does it help the user reach the goal?', '"Please read our refund policy."'],
            ['[[Relevance]]', 'Does it address the question?', '"Our support team works Sunday to Thursday."'],
            ['Logical coherence', 'Does it hold together, with no contradictions?', '"Refunds are not possible. Open a ticket to get your refund."'],
            ['Following instructions', 'Does it obey the instructions in the prompt?', 'A long essay when the prompt said "answer in one sentence".'],
            ['Professional style and tone', 'Is the tone right for a professional setting?', '"lol just open a ticket"'],
            ['Harmfulness, Stereotyping', 'Is there harmful content or a stereotype?', 'An insult, or a generalization about a group of people.'],
            ['Refusal', 'Did the model decline to answer?', '"I cannot help with that." (for a legitimate question)']
          ],
          he: [
            ['[[Correctness]]', 'האם זה נכון עובדתית?', '"You have 60 days."'],
            ['[[Completeness]]', 'האם זה מכסה כל חלק של השאלה?', '"You have 30 days." (חסר איך לבקש)'],
            ['[[Faithfulness]]', 'האם זה אומר רק מה שההקשר תומך בו?', '"30 days, and we refund within 24 hours." (החלק השני מומצא)'],
            ['[[Helpfulness]]', 'האם זה עוזר למשתמש להגיע למטרה?', '"Please read our refund policy."'],
            ['[[Relevance]]', 'האם זה מתייחס לשאלה?', '"Our support team works Sunday to Thursday."'],
            ['Logical coherence', 'האם זה מחזיק מים, בלי סתירות?', '"Refunds are not possible. Open a ticket to get your refund."'],
            ['Following instructions', 'האם זה מציית להוראות בפרומפט?', 'חיבור ארוך כשהפרומפט אמר "answer in one sentence".'],
            ['Professional style and tone', 'האם הטון מתאים לסביבה מקצועית?', '"lol just open a ticket"'],
            ['Harmfulness, Stereotyping', 'האם יש תוכן מזיק או סטריאוטיפ?', 'עלבון, או הכללה על קבוצת אנשים.'],
            ['Refusal', 'האם המודל סירב לענות?', '"I cannot help with that." (לשאלה לגיטימית)']
          ] }, },
        { t: 'note', kind: 'jargon', en: 'These are the 11 built-in judge metrics of Bedrock model evaluation. In the API each has an ID that starts with `Builtin.`: `Builtin.Correctness`, `Builtin.Completeness`, `Builtin.Faithfulness`, `Builtin.Helpfulness`, `Builtin.Coherence`, `Builtin.Relevance`, `Builtin.FollowingInstructions`, `Builtin.ProfessionalStyleAndTone`, `Builtin.Harmfulness`, `Builtin.Stereotyping`, `Builtin.Refusal`. Other tools call faithfulness "groundedness" and relevance "answer relevance". Same ideas, different names.', he: 'אלה 11 מטריקות ה-judge המובנות של Bedrock model evaluation. ב-API לכל אחת יש ID שמתחיל ב-`Builtin.`: ‏`Builtin.Correctness`, ‏`Builtin.Completeness`, ‏`Builtin.Faithfulness`, ‏`Builtin.Helpfulness`, ‏`Builtin.Coherence`, ‏`Builtin.Relevance`, ‏`Builtin.FollowingInstructions`, ‏`Builtin.ProfessionalStyleAndTone`, ‏`Builtin.Harmfulness`, ‏`Builtin.Stereotyping`, ‏`Builtin.Refusal`. כלים אחרים קוראים ל-faithfulness ‏"groundedness" ול-relevance ‏"answer relevance". אותם רעיונות, שמות שונים.' },
        { t: 'note', kind: 'warn', en: '**Correct is not the same as faithful.** An answer can be correct but not faithful: the model answered from its own memory and happened to be right, although the context did not say it. And it can be faithful but not correct: the retrieved document was outdated, and the model repeated it loyally. In RAG you measure both.', he: '**נכון זה לא אותו דבר כמו נאמן.** תשובה יכולה להיות נכונה אבל לא נאמנה: המודל ענה מהזיכרון שלו ובמקרה צדק, אף שההקשר לא אמר את זה. והיא יכולה להיות נאמנה אבל לא נכונה: המסמך שאוחזר היה מיושן, והמודל חזר עליו בנאמנות. ב-RAG מודדים את שניהם.' },
        { t: 'quiz', q: { en: 'Context: "The Pro plan costs 40 dollars a month." Answer: "The Pro plan costs 40 dollars a month and includes 24/7 phone support." The Pro plan really does include phone support, but the context does not say so. How does this answer score?', he: 'הקשר: "The Pro plan costs 40 dollars a month." תשובה: "The Pro plan costs 40 dollars a month and includes 24/7 phone support." תוכנית Pro באמת כוללת תמיכה טלפונית, אבל ההקשר לא אומר את זה. איך התשובה הזו מדורגת?' },
          options: { en: ['Low correctness, high faithfulness', 'High correctness, low faithfulness', 'Low on both', 'High on both'], he: ['Correctness נמוך, faithfulness גבוה', 'Correctness גבוה, faithfulness נמוך', 'נמוך בשניהם', 'גבוה בשניהם'] },
          answer: 1, explain: { en: 'The facts are true, so correctness is high. But one of them is not supported by the context, so faithfulness is low. Today the model guessed right. Tomorrow it will guess wrong in the same way, and that is why you track faithfulness.', he: 'העובדות נכונות, ולכן correctness גבוה. אבל אחת מהן לא נתמכת בהקשר, ולכן faithfulness נמוך. היום המודל ניחש נכון. מחר הוא ינחש לא נכון באותה צורה, ובגלל זה עוקבים אחרי faithfulness.' } },
        { t: 'h', en: 'Metrics for retrieval (RAG)', he: 'מטריקות לאחזור (RAG)' },
        { t: 'p', en: 'A RAG system has two parts, and each can fail alone. So there are metrics for the **retrieved chunks**, before any answer is written:', he: 'למערכת RAG יש שני חלקים, וכל אחד יכול להיכשל לבד. לכן יש מטריקות ל-**chunks שאוחזרו**, לפני שנכתבת תשובה כלשהי:' },
        { t: 'table', head: { en: ['Metric (ID)', 'The question it answers', 'Low score means'], he: ['מטריקה (ID)', 'השאלה שהיא עונה עליה', 'ציון נמוך אומר'] }, rows: {
          en: [
            ['[[Context relevance]] (`Builtin.ContextRelevance`)', 'Are the retrieved chunks about the question?', 'The search brings noise.'],
            ['[[Context coverage]] (`Builtin.ContextCoverage`)', 'Do the chunks contain everything the reference answer needs? Needs ground truth.', 'The search misses needed information.'],
            ['[[Citation precision]] (`Builtin.CitationPrecision`)', 'Are the cited passages really the right ones?', 'The answer cites sources that do not support it.'],
            ['Citation coverage (`Builtin.CitationCoverage`)', 'Is the answer backed by the cited passages?', 'Parts of the answer have no source.']
          ],
          he: [
            ['[[Context relevance]] (`Builtin.ContextRelevance`)', 'האם ה-chunks שאוחזרו עוסקים בשאלה?', 'החיפוש מביא רעש.'],
            ['[[Context coverage]] (`Builtin.ContextCoverage`)', 'האם ה-chunks מכילים את כל מה שתשובת הייחוס צריכה? דורש ground truth.', 'החיפוש מפספס מידע נדרש.'],
            ['[[Citation precision]] (`Builtin.CitationPrecision`)', 'האם הקטעים שצוטטו הם באמת הנכונים?', 'התשובה מצטטת מקורות שלא תומכים בה.'],
            ['Citation coverage (`Builtin.CitationCoverage`)', 'האם התשובה מגובה בקטעים שצוטטו?', 'לחלקים מהתשובה אין מקור.']
          ] } },
        { t: 'p', en: 'Now you can diagnose a RAG system like a doctor:', he: 'עכשיו אפשר לאבחן מערכת RAG כמו רופא:' },
        { t: 'table', head: { en: ['Retrieval scores', 'Answer scores', 'Where the problem is', 'What to fix'], he: ['ציוני אחזור', 'ציוני תשובה', 'איפה הבעיה', 'מה לתקן'] }, rows: {
          en: [['Low context coverage', 'Low correctness', 'Retrieval: the right text was never found', 'Chunking, embeddings, number of results, hybrid search'], ['High', 'Low faithfulness', 'Generation: the model ignores or adds to the context', 'Prompt ("answer only from context"), model, temperature'], ['High', 'Low completeness', 'Generation: the model stops too early', 'Prompt, maxTokens'], ['Low context relevance, high coverage', 'OK', 'Retrieval brings the answer plus a lot of noise', 'Fewer results, reranking: you pay for useless tokens']],
          he: [['Context coverage נמוך', 'Correctness נמוך', 'אחזור: הטקסט הנכון בכלל לא נמצא', 'Chunking, ‏embeddings, מספר תוצאות, hybrid search'], ['גבוהים', 'Faithfulness נמוך', 'יצירה: המודל מתעלם מההקשר או מוסיף עליו', 'פרומפט ("answer only from context"), מודל, temperature'], ['גבוהים', 'Completeness נמוך', 'יצירה: המודל עוצר מוקדם מדי', 'פרומפט, maxTokens'], ['Context relevance נמוך, coverage גבוה', 'בסדר', 'האחזור מביא את התשובה ועוד הרבה רעש', 'פחות תוצאות, reranking: אתה משלם על טוקנים מיותרים']] } },
        { t: 'quiz', q: { en: 'A RAG bot gives wrong answers about shipping. You run an evaluation: context coverage is 0.35, faithfulness is 0.95. Where do you look first?', he: 'בוט RAG נותן תשובות שגויות על משלוחים. אתה מריץ evaluation: ‏context coverage הוא 0.35, ‏faithfulness הוא 0.95. איפה מסתכלים קודם?' },
          options: { en: ['The system prompt', 'The temperature', 'The retrieval step: chunking, embeddings, search settings', 'The judge model'], he: ['ב-system prompt', 'ב-temperature', 'בשלב האחזור: chunking, ‏embeddings, הגדרות חיפוש', 'ב-judge model'] },
          answer: 2, explain: { en: 'High faithfulness says the model is loyal to what it receives. Low coverage says it does not receive the right text. The model is doing its job with bad input. Rewriting the prompt would change nothing.', he: 'Faithfulness גבוה אומר שהמודל נאמן למה שהוא מקבל. Coverage נמוך אומר שהוא לא מקבל את הטקסט הנכון. המודל עושה את העבודה שלו עם קלט גרוע. לכתוב מחדש את הפרומפט לא היה משנה כלום.' } },
        { t: 'h', en: 'Algorithmic metrics', he: 'מטריקות אלגוריתמיות' },
        { t: 'p', en: 'Bedrock [[Programmatic evaluation]] uses three metric names with no judge model: **Accuracy** (how close the answer is to the reference; the algorithm depends on the task, for example BERTScore for summarization or F1 for question answering), **[[Robustness]]** (does the score hold when the prompt is slightly changed?) and **[[Toxicity]]**.', he: '[[Programmatic evaluation]] של Bedrock משתמש בשלושה שמות מטריקות בלי judge model: ‏**Accuracy** (כמה התשובה קרובה לתשובת הייחוס; האלגוריתם תלוי במשימה, למשל BERTScore לסיכום או F1 לשאלות ותשובות), **[[Robustness]]** (האם הציון מחזיק כשהפרומפט משתנה מעט?) ו-**[[Toxicity]]**.' },
        { t: 'h', en: 'Metrics for agents', he: 'מטריקות לסוכנים' },
        { t: 'p', en: 'An agent can give a nice final answer after doing the wrong things on the way, or fail the user after ten perfect steps. So agent metrics exist at three levels. In AgentCore these levels are the [[Session]] (the whole conversation), the [[Trace]] (one turn) and the tool call (one [[Span]]):', he: 'סוכן יכול לתת תשובה סופית יפה אחרי שעשה דברים שגויים בדרך, או לאכזב את המשתמש אחרי עשרה צעדים מושלמים. לכן מטריקות לסוכנים קיימות בשלוש רמות. ב-AgentCore הרמות האלה הן ה-[[Session]] (כל השיחה), ה-[[Trace]] (תור אחד) והקריאה לכלי ([[Span]] אחד):' },
        { t: 'table', head: { en: ['Level', 'Built-in evaluators (AgentCore names)', 'The question'], he: ['רמה', 'Evaluators מובנים (שמות AgentCore)', 'השאלה'] }, rows: {
          en: [['Session', '[[Goal success rate]]; Goal success rate with ground truth', 'Did the user get what they came for?'], ['Trace', 'Correctness, Correctness with ground truth, Faithfulness, Helpfulness, Response relevance, Coherence, Conciseness, Instruction following, Harmfulness, Stereotyping, Refusal', 'Was this one response good?'], ['Tool', '[[Tool selection accuracy]], Tool parameter accuracy, Skill selection accuracy, Skill instruction following', 'Did the agent pick the right tool and pass the right arguments?']],
          he: [['Session', '[[Goal success rate]]; ‏Goal success rate with ground truth', 'האם המשתמש קיבל את מה שבא בשבילו?'], ['Trace', 'Correctness, ‏Correctness with ground truth, ‏Faithfulness, ‏Helpfulness, ‏Response relevance, ‏Coherence, ‏Conciseness, ‏Instruction following, ‏Harmfulness, ‏Stereotyping, ‏Refusal', 'האם התשובה האחת הזו הייתה טובה?'], ['Tool', '[[Tool selection accuracy]], ‏Tool parameter accuracy, ‏Skill selection accuracy, ‏Skill instruction following', 'האם הסוכן בחר את הכלי הנכון והעביר את הארגומנטים הנכונים?']] } },
        { t: 'quiz', q: { en: 'A booking agent has high helpfulness on every single response, but the goal success rate is low. What does this pattern tell you?', he: 'לסוכן הזמנות יש helpfulness גבוה בכל תשובה בודדת, אבל ה-goal success rate נמוך. מה הדפוס הזה אומר לך?' },
          options: { en: ['The judge model is broken', 'Each reply sounds good, but conversations do not end with the booking done', 'The tools are too slow', 'The sampling rate is too low'], he: ['ה-judge model שבור', 'כל תשובה נשמעת טוב, אבל שיחות לא מסתיימות עם הזמנה שבוצעה', 'הכלים איטיים מדי', 'ה-sampling rate נמוך מדי'] },
          answer: 1, explain: { en: 'Trace-level metrics judge one turn. Goal success is judged over the whole session. An agent can be polite and helpful in every turn and still go in circles. This is why you need both levels.', he: 'מטריקות ברמת ה-trace שופטות תור אחד. Goal success נשפט על כל הסשן. סוכן יכול להיות מנומס ומועיל בכל תור ועדיין להסתובב במעגלים. לכן צריך את שתי הרמות.' } },
        { t: 'match', prompt: { en: 'Match the failure to the metric that catches it.', he: 'התאם את הכישלון למטריקה שתופסת אותו.' }, pairs: [
          { a: { en: 'The answer adds a fact that is not in the documents', he: 'התשובה מוסיפה עובדה שלא נמצאת במסמכים' }, b: 'Faithfulness' },
          { a: { en: 'The answer covers only half of a two-part question', he: 'התשובה מכסה רק חצי משאלה בשני חלקים' }, b: 'Completeness' },
          { a: { en: 'The search returned chunks about a different product', he: 'החיפוש החזיר chunks על מוצר אחר' }, b: 'Context relevance' },
          { a: { en: 'The agent called get_weather when it needed get_order', he: 'הסוכן קרא ל-get_weather כשהיה צריך get_order' }, b: 'Tool selection accuracy' },
          { a: { en: 'The agent called the right tool with the wrong order ID', he: 'הסוכן קרא לכלי הנכון עם מזהה הזמנה שגוי' }, b: 'Tool parameter accuracy' },
          { a: { en: 'The model says "I cannot help" to a normal question', he: 'המודל אומר "I cannot help" לשאלה רגילה' }, b: 'Refusal' }
        ] },
        { t: 'fill', prompt: { en: 'You configure a Bedrock RAG evaluation of the retrieve-and-generate type. You want to know whether answers are supported by the retrieved text and whether nothing is missing from them. Fill in the two metric IDs.', he: 'אתה מגדיר RAG evaluation של Bedrock מסוג retrieve-and-generate. אתה רוצה לדעת אם התשובות נתמכות בטקסט שאוחזר ואם לא חסר בהן כלום. השלם את שני ה-IDs של המטריקות.' },
          lang: 'python', code: 'metric_names = [\n    "Builtin.{{1}}",     # supported by the retrieved text?\n    "Builtin.{{2}}",     # covers every part of the question?\n]', blanks: [
            { accept: ['Faithfulness'], hint: { en: 'Loyal to the context', he: 'נאמן להקשר' } },
            { accept: ['Completeness'], hint: { en: 'Nothing is missing', he: 'לא חסר כלום' } } ],
          explain: { en: 'Built-in metric IDs are `Builtin.` plus the metric name. One trap to know: logical coherence is `Builtin.Coherence` in model evaluation but `Builtin.LogicalCoherence` in RAG evaluation.', he: 'IDs של מטריקות מובנות הם `Builtin.` ועוד שם המטריקה. מלכודת אחת שכדאי להכיר: logical coherence הוא `Builtin.Coherence` ב-model evaluation אבל `Builtin.LogicalCoherence` ב-RAG evaluation.' } },
        { t: 'reveal', q: { en: 'Interview question: "You may track only three metrics for a customer-support RAG bot. Which three, and why?"', he: 'שאלת ראיון: "מותר לך לעקוב רק אחרי שלוש מטריקות לבוט RAG של תמיכת לקוחות. אילו שלוש, ולמה?"' },
          a: { en: 'Faithfulness, because an invented policy is the most expensive failure: the customer acts on it. Context coverage, because it tells me whether retrieval finds what is needed, and it separates retrieval problems from generation problems. And correctness against reference answers on my golden dataset, because in the end the customer needs the right answer. If I were allowed a fourth, completeness. I would not start with tone or coherence: modern models rarely fail there, so the numbers would look great and tell me nothing.', he: 'Faithfulness, כי נוהל מומצא הוא הכישלון הכי יקר: הלקוח פועל לפיו. Context coverage, כי הוא אומר לי אם האחזור מוצא את מה שצריך, והוא מפריד בין בעיות אחזור לבעיות יצירה. ו-correctness מול תשובות ייחוס ב-golden dataset שלי, כי בסוף הלקוח צריך את התשובה הנכונה. אם היו מרשים לי רביעית, completeness. לא הייתי מתחיל עם טון או coherence: מודלים מודרניים כמעט לא נכשלים שם, אז המספרים היו נראים מצוין ולא אומרים לי כלום.' } }
      ]
    },
    {
      id: 'm11l3', minutes: 15,
      title: { en: 'Bedrock evaluation jobs: models and RAG', he: 'Evaluation jobs של Bedrock: מודלים ו-RAG' },
      blocks: [
        { t: 'p', en: 'Amazon Bedrock runs evaluations as batch jobs. You point an [[Evaluation job]] at a dataset in S3, choose what to evaluate and which metrics to use, and get a report. There are four kinds, all created with one API: `CreateEvaluationJob` in the `bedrock` client.', he: 'Amazon Bedrock מריץ evaluations כ-jobs אצוותיים. מפנים [[Evaluation job]] ל-dataset ב-S3, בוחרים מה לבדוק ובאילו מטריקות להשתמש, ומקבלים דוח. יש ארבעה סוגים, וכולם נוצרים עם API אחד: `CreateEvaluationJob` ב-client ‏`bedrock`.' },
        { t: 'table', head: { en: ['Kind', 'Who scores', 'Use it for'], he: ['סוג', 'מי נותן ציון', 'משמש ל'] }, rows: {
          en: [
            ['**Automatic (programmatic)** model evaluation', 'Algorithms: Accuracy, Robustness, Toxicity', 'A quick, cheap first comparison of models on a standard task (general text generation, summarization, question and answer, classification). Has built-in datasets.'],
            ['**Model as a judge**', 'An evaluator (judge) model, with the 11 built-in metrics or your custom ones', 'Judging quality of answers on your own prompts.'],
            ['**Human**', 'Your own work team', 'Subjective quality, brand voice, a final check before a big launch.'],
            ['**RAG evaluation**', 'A judge model', 'A knowledge base or any RAG system: retrieval alone, or retrieval plus the answer.']
          ],
          he: [
            ['Model evaluation ‏**Automatic (programmatic)**', 'אלגוריתמים: Accuracy, ‏Robustness, ‏Toxicity', 'השוואה ראשונה מהירה וזולה של מודלים על משימה סטנדרטית (general text generation, ‏summarization, ‏question and answer, ‏classification). יש datasets מובנים.'],
            ['**Model as a judge**', 'Evaluator (judge) model, עם 11 המטריקות המובנות או מטריקות מותאמות שלך', 'שיפוט איכות של תשובות על פרומפטים משלך.'],
            ['**Human**', 'צוות עבודה משלך', 'איכות סובייקטיבית, קול המותג, בדיקה אחרונה לפני השקה גדולה.'],
            ['**RAG evaluation**', 'Judge model', 'Knowledge base או כל מערכת RAG: אחזור לבד, או אחזור ועוד התשובה.']
          ] } },
        { t: 'list', en: [
          'Every job type takes at most **1,000 prompts** per dataset.',
          'A judge job has two models: the [[Generator model]] that writes the answers and the evaluator model that scores them. Both must be in the same Region. The judge returns a score **and an explanation** for each prompt.',
          'A human job can compare up to two inference sources. The reviewers are a private work team that you choose, and they rate with methods such as thumbs up/down or a Likert scale.',
          'Results appear as a report card in the console and as files in the S3 output location.'
        ], he: [
          'כל סוג job מקבל לכל היותר **1,000 פרומפטים** ל-dataset.',
          'ל-judge job יש שני מודלים: ה-[[Generator model]] שכותב את התשובות וה-evaluator model שנותן להן ציון. שניהם חייבים להיות באותו Region. ה-judge מחזיר ציון **והסבר** לכל פרומפט.',
          'Human job יכול להשוות עד שני מקורות inference. הבודקים הם צוות עבודה פרטי שאתה בוחר, והם מדרגים בשיטות כמו thumbs up/down או סולם Likert.',
          'התוצאות מופיעות כ-report card בקונסול וכקבצים במיקום הפלט ב-S3.'
        ] },
        { t: 'quiz', q: { en: 'You must choose between three models for summarizing support tickets, and you have 200 real tickets with summaries that your team wrote. You want a result today, at the lowest cost. Which job do you start with?', he: 'אתה צריך לבחור בין שלושה מודלים לסיכום טיקטים של תמיכה, ויש לך 200 טיקטים אמיתיים עם סיכומים שהצוות שלך כתב. אתה רוצה תוצאה היום, בעלות הנמוכה ביותר. עם איזה job מתחילים?' },
          options: { en: ['A human evaluation with 50 workers', 'A RAG retrieve-only evaluation', 'No job: read ten summaries yourself', 'An automatic (programmatic) evaluation with your own dataset, one job per model'], he: ['Human evaluation עם 50 עובדים', 'RAG evaluation מסוג retrieve-only', 'בלי job: לקרוא עשרה סיכומים בעצמך', 'Evaluation מסוג automatic (programmatic) עם dataset משלך, job אחד לכל מודל'] },
          answer: 3, explain: { en: 'You have reference summaries, so algorithmic accuracy can be computed with no judge tokens. An automatic job takes one model, so you run three jobs. Afterwards you can run a judge job on the best two for a deeper look. Reading ten yourself is the "looks fine" trap.', he: 'יש לך סיכומי ייחוס, אז אפשר לחשב accuracy אלגוריתמי בלי טוקנים של judge. Automatic job מקבל מודל אחד, אז מריצים שלושה jobs. אחר כך אפשר להריץ judge job על שני הטובים למבט עמוק יותר. לקרוא עשרה בעצמך זו מלכודת ה"נראה בסדר".' } },
        { t: 'h', en: 'The dataset format', he: 'פורמט ה-dataset' },
        { t: 'p', en: 'A dataset is a [[JSONL]] file in S3: one JSON object per line. For model evaluation each line has a `prompt`, an optional `referenceResponse` (the [[Ground truth]]) and an optional `category`.', he: 'Dataset הוא קובץ [[JSONL]] ב-S3: אובייקט JSON אחד בכל שורה. ל-model evaluation בכל שורה יש `prompt`, ‏`referenceResponse` אופציונלי (ה-[[Ground truth]]) ו-`category` אופציונלי.' },
        { t: 'code', lang: 'json', code: '{"prompt":"Aurillac is the capital of","category":"Capitals","referenceResponse":"Cantal"}\n{"prompt":"What is the refund window?","category":"Refunds","referenceResponse":"30 days from the purchase date."}', caption: { en: 'Two lines = two test cases. `category` lets the report split scores by topic.', he: 'שתי שורות = שני מקרי בדיקה. `category` מאפשר לדוח לפצל ציונים לפי נושא.' } },
        { t: 'list', en: [
          '`referenceResponse` is required for the algorithmic accuracy and robustness metrics. In a judge job it is optional; Correctness and Completeness use it when it is there.',
          '**Always fill in `category`.** An average of 0.85 can hide a category that scores 0.40. Per-category scores show you where the product is weak.'
        ], he: [
          '`referenceResponse` הוא חובה למטריקות האלגוריתמיות accuracy ו-robustness. ב-judge job הוא אופציונלי; ‏Correctness ו-Completeness משתמשות בו כשהוא קיים.',
          '**תמיד למלא `category`.** ממוצע של 0.85 יכול להסתיר קטגוריה שמקבלת 0.40. ציונים לפי קטגוריה מראים לך איפה המוצר חלש.'
        ] },
        { t: 'fill', prompt: { en: 'Write one dataset line for a judge job. It has the question, the human-approved answer and a topic label.', he: 'כתוב שורת dataset אחת ל-judge job. יש בה את השאלה, את התשובה שאדם אישר ותווית נושא.' },
          lang: 'json', code: '{"{{1}}": "How long is the laptop warranty?", "{{2}}": "Two years, covering hardware defects.", "{{3}}": "Warranty"}', blanks: [
            { accept: ['prompt'], hint: { en: 'The input to the model', he: 'הקלט למודל' } },
            { accept: ['referenceResponse'], hint: { en: 'camelCase: reference + Response', he: 'camelCase: reference + Response' } },
            { accept: ['category'], hint: { en: 'The topic label', he: 'תווית הנושא' } } ],
          explain: { en: '`prompt`, `referenceResponse`, `category`. The whole object must be on one line, with no comma between lines: that is what makes it JSONL.', he: '`prompt`, ‏`referenceResponse`, ‏`category`. כל האובייקט חייב להיות בשורה אחת, בלי פסיק בין שורות: זה מה שהופך את זה ל-JSONL.' } },
        { t: 'h', en: 'Bring your own inference responses', he: 'Bring your own inference responses' },
        { t: 'p', en: 'Often the thing you want to judge is not a bare Bedrock model. It is your whole app: prompt template, tools, post-processing. Or a model that runs somewhere else. With [[Bring your own inference]] you run your app yourself, save its answers into the dataset, and the job only **scores** them.', he: 'לעתים קרובות הדבר שרוצים לשפוט הוא לא מודל Bedrock חשוף. זו כל האפליקציה שלך: תבנית פרומפט, כלים, עיבוד שאחרי. או מודל שרץ במקום אחר. עם [[Bring your own inference]] מריצים את האפליקציה לבד, שומרים את התשובות שלה ב-dataset, וה-job רק **נותן להן ציון**.' },
        { t: 'code', lang: 'json', code: '{"prompt":"What is the refund window?","referenceResponse":"30 days from the purchase date.","category":"Refunds","modelResponses":[{"response":"You can get a refund within 30 days of buying.","modelIdentifier":"support-bot-v7"}]}', caption: { en: 'One line with a precomputed answer. In a judge job: exactly one response per prompt, and one `modelIdentifier` for the whole job.', he: 'שורה אחת עם תשובה שחושבה מראש. ב-judge job: בדיוק תשובה אחת לכל פרומפט, ו-`modelIdentifier` אחד לכל ה-job.' } },
        { t: 'note', kind: 'tip', en: 'This is the mode you will use most as an app developer. It evaluates **what your users really get**, and it lets you compare version 7 of your app with version 8 using the same judge and the same questions. In the job you name the source with the same identifier that appears in the dataset.', he: 'זה המצב שתשתמש בו הכי הרבה כמפתח אפליקציות. הוא בודק **מה שהמשתמשים שלך באמת מקבלים**, ומאפשר להשוות את גרסה 7 של האפליקציה לגרסה 8 עם אותו judge ואותן שאלות. ב-job נותנים למקור את אותו מזהה שמופיע ב-dataset.' },
        { t: 'h', en: 'Lab: create a judge evaluation', he: 'מעבדה: יצירת judge evaluation' },
        { t: 'console', service: 'Amazon Bedrock', nav: ['#Inference and assessment', 'Evaluations'], active: 'Evaluations',
          crumbs: ['Amazon Bedrock', 'Evaluations', 'Create'], heading: 'Automatic: Model as a judge',
          task: { en: 'Your app `support-bot-v7` already produced answers for the golden dataset, and they are saved in the dataset file. Create a judge evaluation named `support-bot-v7-judge`. Use Amazon Nova Pro as the judge. The answers come from your own app, so pick the right inference source and give it the same name as in the dataset. You have reference answers and want to know two things: are the answers right, and is anything missing from them. Let Bedrock create the IAM role.', he: 'האפליקציה שלך `support-bot-v7` כבר יצרה תשובות ל-golden dataset, והן שמורות בקובץ ה-dataset. צור judge evaluation בשם `support-bot-v7-judge`. השתמש ב-Amazon Nova Pro כ-judge. התשובות מגיעות מהאפליקציה שלך, אז בחר את מקור ה-inference הנכון ותן לו את אותו שם כמו ב-dataset. יש לך תשובות ייחוס ואתה רוצה לדעת שני דברים: האם התשובות נכונות, והאם חסר בהן משהו. תן ל-Bedrock ליצור את ה-IAM role.' },
          panels: [
            { title: 'Model evaluation details', n: 1, fields: [
              { label: 'Evaluation name', type: 'input', value: '', placeholder: 'my-evaluation', help: 'Lowercase letters, numbers and hyphens.', expect: 'support-bot-v7-judge', hint: { en: 'The brief gives the name: support-bot-v7-judge', he: 'השם מופיע בתיאור המשימה: support-bot-v7-judge' } },
              { label: 'Evaluator model', type: 'select', options: ['Select model', 'Amazon Nova Pro', 'Claude Sonnet 4.6', 'Mistral Large'], value: 'Select model', n: 2, expect: 'Amazon Nova Pro', hint: { en: 'The brief says Amazon Nova Pro is the judge.', he: 'בתיאור המשימה כתוב ש-Amazon Nova Pro הוא ה-judge.' } } ] },
            { title: 'Inference source', n: 3, fields: [
              { label: 'Select source', type: 'radio', options: ['Bedrock models', 'Bring your own inference responses'], value: 'Bedrock models', expect: 'Bring your own inference responses', hint: { en: 'The answers already exist in the dataset, so Bedrock should not generate them again.', he: 'התשובות כבר קיימות ב-dataset, אז Bedrock לא צריך ליצור אותן שוב.' } },
              { label: 'Source name', type: 'input', value: '', help: 'Must match the modelIdentifier in your dataset.', expect: 'support-bot-v7', hint: { en: 'The same identifier as in the dataset: support-bot-v7', he: 'אותו מזהה כמו ב-dataset: ‏support-bot-v7' } } ] },
            { title: 'Metrics', n: 4, fields: [
              { label: 'Correctness', type: 'checkbox', value: false, expect: true, hint: { en: '"Are the answers right?" is Correctness.', he: '"האם התשובות נכונות?" זה Correctness.' } },
              { label: 'Completeness', type: 'checkbox', value: false, expect: true, hint: { en: '"Is anything missing?" is Completeness.', he: '"האם חסר משהו?" זה Completeness.' } },
              { label: 'Professional style and tone', type: 'checkbox', value: false },
              { label: 'Harmfulness', type: 'checkbox', value: false } ] },
            { title: 'Datasets', n: 5, fields: [
              { label: 'Choose a prompt dataset', type: 'text', value: 's3://my-eval-bucket/golden/support-v7.jsonl' },
              { label: 'Evaluation results', type: 'text', value: 's3://my-eval-bucket/results/' } ] },
            { title: 'Amazon Bedrock IAM role - Permissions', n: 6, fields: [
              { label: 'Service role', type: 'radio', options: ['Use an existing service role', 'Create and use a new service role'], value: 'Use an existing service role', expect: 'Create and use a new service role', hint: { en: 'The brief says to let Bedrock create the role.', he: 'בתיאור המשימה כתוב לתת ל-Bedrock ליצור את ה-role.' } } ] }
          ],
          buttons: ['Cancel', 'Create'],
          callouts: [
            { n: 1, en: 'Job names are lowercase with hyphens, up to 63 characters. Put the app version in the name so you can find the run later.', he: 'שמות של jobs הם באותיות קטנות עם מקפים, עד 63 תווים. שים את גרסת האפליקציה בשם כדי שתוכל למצוא את הריצה אחר כך.' },
            { n: 2, en: 'The judge. Keep the same judge model between runs, or the scores are not comparable.', he: 'ה-judge. שמור על אותו judge model בין ריצות, אחרת הציונים לא ניתנים להשוואה.' },
            { n: 3, en: '"Bedrock models" makes Bedrock call a model for every prompt. "Bring your own inference responses" only scores the answers in the file.', he: '"Bedrock models" גורם ל-Bedrock לקרוא למודל לכל פרומפט. "Bring your own inference responses" רק נותן ציון לתשובות שבקובץ.' },
            { n: 4, en: 'Every metric you tick is one more judge call per prompt. Choose the ones you will act on.', he: 'כל מטריקה שמסמנים היא עוד קריאת judge לכל פרומפט. בוחרים את אלה שתפעל לפיהן.' },
            { n: 5, en: 'Input: the JSONL file. Output: a folder for the result files.', he: 'קלט: קובץ ה-JSONL. פלט: תיקייה לקובצי התוצאות.' },
            { n: 6, en: 'The service role lets the job read the dataset, write the results and call the judge model.', he: 'ה-service role מאפשר ל-job לקרוא את ה-dataset, לכתוב את התוצאות ולקרוא ל-judge model.' }
          ],
          success: { en: 'The job is created. When it completes you get a report card in the console and the detailed files in S3, with a score and an explanation for every prompt.', he: 'ה-job נוצר. כשהוא מסתיים מקבלים report card בקונסול ואת הקבצים המפורטים ב-S3, עם ציון והסבר לכל פרומפט.' },
          caption: { en: 'Simplified. Path in the docs: Evaluations → pane "Model evaluations" → Create → "Automatic: Model as a judge". Pane and field names follow the docs; the list of metrics and judge models is shortened, and "Service role" is our label for the role choice.', he: 'מפושט. הנתיב בתיעוד: Evaluations ← חלונית "Model evaluations" ← Create ← "Automatic: Model as a judge". שמות החלוניות והשדות לפי התיעוד; רשימת המטריקות ומודלי ה-judge מקוצרת, ו-"Service role" היא התווית שלנו לבחירת ה-role.' } },
        { t: 'h', en: 'The same job from code', he: 'אותו job מהקוד' },
        { t: 'code', lang: 'python', code: 'import boto3\nbedrock = boto3.client("bedrock")\n\njob = bedrock.create_evaluation_job(\n    jobName="support-bot-v7-judge",\n    roleArn="arn:aws:iam::111122223333:role/eval-service-role",\n    applicationType="ModelEvaluation",\n    inferenceConfig={"models": [{\n        "precomputedInferenceSource": {"inferenceSourceIdentifier": "support-bot-v7"}\n    }]},\n    evaluationConfig={"automated": {\n        "datasetMetricConfigs": [{\n            "taskType": "General",\n            "dataset": {"name": "golden-support",\n                        "datasetLocation": {"s3Uri": "s3://my-eval-bucket/golden/support-v7.jsonl"}},\n            "metricNames": ["Builtin.Correctness", "Builtin.Completeness"],\n        }],\n        "evaluatorModelConfig": {"bedrockEvaluatorModels": [\n            {"modelIdentifier": "<judge-model-id>"}\n        ]},\n    }},\n    outputDataConfig={"s3Uri": "s3://my-eval-bucket/results/"},\n)\nprint(job["jobArn"])', caption: { en: 'To let Bedrock generate the answers instead, replace `precomputedInferenceSource` with `bedrockModel: {"modelIdentifier": ...}`. Follow the job with `GetEvaluationJob`.', he: 'כדי לתת ל-Bedrock ליצור את התשובות במקום, מחליפים את `precomputedInferenceSource` ב-`bedrockModel: {"modelIdentifier": ...}`. עוקבים אחרי ה-job עם `GetEvaluationJob`.' } },
        { t: 'h', en: 'RAG evaluation', he: 'RAG evaluation' },
        { t: 'p', en: 'A RAG evaluation job (`applicationType: "RagEvaluation"`) has two types:', he: 'ל-RAG evaluation job ‏(`applicationType: "RagEvaluation"`) יש שני סוגים:' },
        { t: 'table', head: { en: ['Type', 'What runs', 'Metrics'], he: ['סוג', 'מה רץ', 'מטריקות'] }, rows: {
          en: [['**Retrieve only**', 'Only the search. No answer is written.', 'Context relevance, Context coverage'], ['**Retrieve and generate**', 'Search plus the answer.', 'Correctness, Completeness, Helpfulness, Logical coherence, Faithfulness, Citation precision, Citation coverage, Harmfulness, Stereotyping, Refusal']],
          he: [['**Retrieve only**', 'רק החיפוש. לא נכתבת תשובה.', 'Context relevance, ‏Context coverage'], ['**Retrieve and generate**', 'חיפוש ועוד התשובה.', 'Correctness, ‏Completeness, ‏Helpfulness, ‏Logical coherence, ‏Faithfulness, ‏Citation precision, ‏Citation coverage, ‏Harmfulness, ‏Stereotyping, ‏Refusal']] } },
        { t: 'p', en: 'The RAG source is either an Amazon Bedrock Knowledge Base or your own RAG system through bring-your-own-inference (you add the retrieved passages and the answer to each line). One RAG source per job. The dataset format is different: it is built from conversation turns.', he: 'מקור ה-RAG הוא Amazon Bedrock Knowledge Base או מערכת RAG משלך דרך bring-your-own-inference (מוסיפים לכל שורה את הקטעים שאוחזרו ואת התשובה). מקור RAG אחד ל-job. פורמט ה-dataset שונה: הוא בנוי מתורות של שיחה.' },
        { t: 'code', lang: 'json', code: '{"conversationTurns":[{"prompt":{"content":[{"text":"What is the refund window?"}]},"referenceResponses":[{"content":[{"text":"30 days from the purchase date."}]}]}]}', caption: { en: 'One line of a RAG dataset. Retrieve-and-generate allows up to 5 turns per conversation; retrieve-only is single turn.', he: 'שורה אחת של RAG dataset. ב-retrieve-and-generate אפשר עד 5 תורות לשיחה; ב-retrieve-only תור אחד.' } },
        { t: 'fill', prompt: { en: 'Complete one line of a RAG evaluation dataset with a question and its reference answer.', he: 'השלם שורה אחת של RAG evaluation dataset עם שאלה ותשובת הייחוס שלה.' },
          lang: 'json', code: '{"{{1}}":[{"{{2}}":{"content":[{"text":"How fast is express shipping?"}]},"{{3}}":[{"content":[{"text":"1 to 2 business days."}]}]}]}', blanks: [
            { accept: ['conversationTurns'], hint: { en: 'A list of turns of a conversation (camelCase)', he: 'רשימת תורות של שיחה (camelCase)' } },
            { accept: ['prompt'], hint: { en: 'The user question of this turn', he: 'השאלה של המשתמש בתור הזה' } },
            { accept: ['referenceResponses'], hint: { en: 'Plural: reference + Responses', he: 'ברבים: reference + Responses' } } ],
          explain: { en: 'Model evaluation uses flat keys (`prompt`, `referenceResponse`). RAG evaluation wraps them in `conversationTurns`, and the reference is plural: `referenceResponses`. Mixing the two formats is the most common reason a job fails at the start.', he: 'Model evaluation משתמש במפתחות שטוחים (`prompt`, ‏`referenceResponse`). ‏RAG evaluation עוטף אותם ב-`conversationTurns`, והייחוס ברבים: `referenceResponses`. ערבוב בין שני הפורמטים הוא הסיבה הנפוצה ביותר לכך ש-job נכשל בהתחלה.' } },
        { t: 'quiz', q: { en: 'You changed the chunking strategy of a knowledge base and want to know quickly and cheaply whether search got better. Which RAG job type do you run?', he: 'שינית את אסטרטגיית ה-chunking של knowledge base ואתה רוצה לדעת מהר ובזול אם החיפוש השתפר. איזה סוג RAG job מריצים?' },
          options: { en: ['Retrieve only, with Context relevance and Context coverage', 'Retrieve and generate, with all ten metrics', 'A human evaluation', 'An automatic model evaluation with Robustness'], he: ['Retrieve only, עם Context relevance ו-Context coverage', 'Retrieve and generate, עם כל עשר המטריקות', 'Human evaluation', 'Automatic model evaluation עם Robustness'] },
          answer: 0, explain: { en: 'Chunking affects retrieval. Retrieve-only measures exactly that part, with no generation tokens and no noise from the answering model. Remember that Context coverage needs reference answers in the dataset.', he: 'Chunking משפיע על האחזור. Retrieve-only מודד בדיוק את החלק הזה, בלי טוקנים של יצירה ובלי רעש מהמודל שעונה. זכור ש-Context coverage דורש תשובות ייחוס ב-dataset.' } },
        { t: 'h', en: 'Custom metrics', he: 'Custom metrics' },
        { t: 'p', en: 'The built-in metrics do not know your business. "Does the answer mention the legal disclaimer?" "Is the reply in the customer\'s language?" For that you write a [[Custom metric]]: a judge prompt and an optional [[Rating scale]]. Up to 10 custom metrics per job; the judge prompt can be up to 5,000 characters.', he: 'המטריקות המובנות לא מכירות את העסק שלך. "האם התשובה מזכירה את ההסתייגות המשפטית?" "האם התשובה בשפה של הלקוח?" בשביל זה כותבים [[Custom metric]]: פרומפט judge ו-[[Rating scale]] אופציונלי. עד 10 custom metrics ל-job; פרומפט ה-judge יכול להיות עד 5,000 תווים.' },
        { t: 'code', lang: 'json', code: '{\n  "customMetricDefinition": {\n    "metricName": "mentions_disclaimer",\n    "instructions": "You are checking answers of a bank assistant. Decide whether the answer tells the user that this is not financial advice. Judge only this point.\\n\\nQuestion: {{prompt}}\\nAnswer: {{prediction}}",\n    "ratingScale": [\n      {"definition": "Disclaimer present", "value": {"floatValue": 1}},\n      {"definition": "Disclaimer missing", "value": {"floatValue": 0}}\n    ]\n  }\n}', caption: { en: 'The judge prompt uses the variables {{prompt}}, {{prediction}} (the answer) and, when you have references, {{ground_truth}}. Place the variables at the end of the instructions.', he: 'פרומפט ה-judge משתמש במשתנים {{prompt}}, ‏{{prediction}} (התשובה) וכשיש ייחוס גם {{ground_truth}}. שמים את המשתנים בסוף ההוראות.' } },
        { t: 'note', kind: 'tip', en: 'Rules for a good judge prompt: judge **one thing** per metric; define every score in words (a short label per value); keep the scale small (0/1 or 1 to 3 is more reliable than 1 to 10); and do not mix number and text values in one scale.', he: 'כללים לפרומפט judge טוב: שופטים **דבר אחד** לכל מטריקה; מגדירים כל ציון במילים (תווית קצרה לכל ערך); שומרים על סולם קטן (0/1 או 1 עד 3 אמין יותר מ-1 עד 10); ולא מערבבים ערכי מספר וטקסט באותו סולם.' },
        { t: 'quiz', q: { en: 'In a custom metric prompt, which variable holds the answer that is being judged?', he: 'בפרומפט של custom metric, איזה משתנה מחזיק את התשובה שנשפטת?' },
          options: { en: ['{{prompt}}', '{{ground_truth}}', '{{prediction}}', '{{answer}}'], he: ['{{prompt}}', '{{ground_truth}}', '{{prediction}}', '{{answer}}'] },
          answer: 2, explain: { en: '`{{prompt}}` is the question, `{{prediction}}` is the model answer, `{{ground_truth}}` is the reference response. There is no `{{answer}}` variable.', he: '`{{prompt}}` הוא השאלה, `{{prediction}}` הוא תשובת המודל, `{{ground_truth}}` הוא תשובת הייחוס. אין משתנה `{{answer}}`.' } },
        { t: 'note', kind: 'info', en: 'What you pay for. Algorithmic scores have no extra charge: you pay only for the model inference. In a judge job you also pay for the judge model tokens at normal on-demand rates. A RAG job adds the knowledge base usage. Human evaluation with your own team adds a fee per completed human task (0.21 dollars in November 2026; check the pricing page).', he: 'על מה משלמים. על ציונים אלגוריתמיים אין חיוב נוסף: משלמים רק על ה-inference של המודל. ב-judge job משלמים גם על הטוקנים של ה-judge model בתעריפי on-demand רגילים. RAG job מוסיף את השימוש ב-knowledge base. ‏Human evaluation עם צוות משלך מוסיף עמלה לכל משימה אנושית שהושלמה (0.21 דולר בנובמבר 2026; בדוק בדף התמחור).' },
        { t: 'reveal', q: { en: 'Interview question: "When do you let Bedrock generate the answers in an evaluation job, and when do you bring your own?"', he: 'שאלת ראיון: "מתי אתה נותן ל-Bedrock ליצור את התשובות ב-evaluation job, ומתי אתה מביא משלך?"' },
          a: { en: 'I let Bedrock generate when the question is about a bare model or a knowledge base: which model is better at this task, or did my chunking change improve retrieval. I bring my own responses when I want to judge the real application: the prompt template, the tools, the post-processing, maybe a model outside Bedrock. Then I run the app on the golden dataset in my pipeline, write the answers into the JSONL with one identifier per app version, and use the job only as a judge. That is the setup I would use in CI, because it measures what users actually get.', he: 'אני נותן ל-Bedrock ליצור כשהשאלה היא על מודל חשוף או על knowledge base: איזה מודל טוב יותר במשימה הזו, או האם שינוי ה-chunking שלי שיפר את האחזור. אני מביא תשובות משלי כשאני רוצה לשפוט את האפליקציה האמיתית: תבנית הפרומפט, הכלים, העיבוד שאחרי, אולי מודל מחוץ ל-Bedrock. אז אני מריץ את האפליקציה על ה-golden dataset ב-pipeline שלי, כותב את התשובות ל-JSONL עם מזהה אחד לכל גרסת אפליקציה, ומשתמש ב-job רק כ-judge. זו ההגדרה שהייתי משתמש בה ב-CI, כי היא מודדת מה שהמשתמשים באמת מקבלים.' } }
      ]
    },
    {
      id: 'm11l4', minutes: 14,
      title: { en: 'AgentCore Evaluations: scoring agents', he: 'AgentCore Evaluations: לתת ציון לסוכנים' },
      blocks: [
        { t: 'p', en: 'A Bedrock evaluation job judges question-and-answer pairs. An agent is more than that: one user request becomes a chain of model calls and tool calls, and a conversation has many turns. **Amazon Bedrock AgentCore Evaluations** scores agent behaviour from its OpenTelemetry traces, with [[LLM-as-a-judge]] or with your own code. It can do this continuously on live traffic or on demand.', he: 'Evaluation job של Bedrock שופט זוגות של שאלה ותשובה. סוכן הוא יותר מזה: בקשה אחת של משתמש הופכת לשרשרת של קריאות למודל וקריאות לכלים, ולשיחה יש הרבה תורות. **Amazon Bedrock AgentCore Evaluations** נותן ציון להתנהגות הסוכן מתוך ה-traces שלו ב-OpenTelemetry, עם [[LLM-as-a-judge]] או עם קוד משלך. הוא יכול לעשות את זה ברציפות על תעבורה חיה או לפי דרישה.' },
        { t: 'note', kind: 'info', en: 'The input of AgentCore Evaluations is **traces**, not a dataset file. So the agent must send traces first: observability has to be on. The agent does not have to run on AgentCore Runtime. Supported frameworks include Strands, LangGraph, OpenAI Agents, LlamaIndex, Google ADK, the Claude Agent SDK and the Vercel AI SDK, plus generic OpenTelemetry.', he: 'הקלט של AgentCore Evaluations הוא **traces**, לא קובץ dataset. לכן הסוכן חייב קודם לשלוח traces: ‏observability צריך להיות פעיל. הסוכן לא חייב לרוץ על AgentCore Runtime. ה-frameworks הנתמכים כוללים Strands, ‏LangGraph, ‏OpenAI Agents, ‏LlamaIndex, ‏Google ADK, ‏Claude Agent SDK ו-Vercel AI SDK, ועוד OpenTelemetry כללי.' },
        { t: 'h', en: 'Three levels', he: 'שלוש רמות' },
        { t: 'arch', layers: [
          { title: { en: 'Session: the whole conversation', he: 'Session: כל השיחה' }, items: [{ en: 'Evaluator example: Goal success rate', he: 'Evaluator לדוגמה: Goal success rate' }] },
          { title: { en: 'Trace: one turn (one request and its response)', he: 'Trace: תור אחד (בקשה אחת והתשובה שלה)' }, items: [{ en: 'Helpfulness', he: 'Helpfulness' }, { en: 'Faithfulness', he: 'Faithfulness' }, { en: 'Correctness', he: 'Correctness' }] },
          { title: { en: 'Tool: one tool call (one span)', he: 'Tool: קריאה אחת לכלי (span אחד)' }, items: [{ en: 'Tool selection accuracy', he: 'Tool selection accuracy' }, { en: 'Tool parameter accuracy', he: 'Tool parameter accuracy' }] }
        ], caption: { en: 'A session contains traces. A trace contains spans. Each evaluator works at one level.', he: 'Session מכיל traces. ‏Trace מכיל spans. כל evaluator עובד ברמה אחת.' } },
        { t: 'h', en: 'Evaluators', he: 'Evaluators' },
        { t: 'list', en: [
          '**Built-in** [[Evaluator]]s have a fixed prompt and a fixed judge model. Their IDs look like `Builtin.<Name>`. IDs you can rely on: `Builtin.GoalSuccessRate`, `Builtin.Helpfulness`, `Builtin.SkillSelectionAccuracy`, `Builtin.SkillInstructionFollowing`. For the others in the table of lesson 2, take the exact ID from the docs or the console list; do not guess the spelling.',
          '**Custom** evaluators: an LLM judge with your own prompt and model; a **code-based** evaluator (a Lambda function, for checks that have one right answer); or a **multi-dimension** evaluator that scores up to 50 named dimensions in one call.',
          '**Third-party** evaluators from DeepEval and AutoEval.',
          '**Insight** evaluators such as `Builtin.FailureAnalysis`, which explain failures instead of giving a single score.'
        ], he: [
          '[[Evaluator]]s **מובנים** מגיעים עם פרומפט קבוע ו-judge model קבוע. ה-IDs שלהם נראים כמו `Builtin.<Name>`. ‏IDs שאפשר לסמוך עליהם: `Builtin.GoalSuccessRate`, ‏`Builtin.Helpfulness`, ‏`Builtin.SkillSelectionAccuracy`, ‏`Builtin.SkillInstructionFollowing`. לגבי האחרים בטבלה של שיעור 2, קח את ה-ID המדויק מהתיעוד או מהרשימה בקונסול; אל תנחש את האיות.',
          'Evaluators **מותאמים**: ‏LLM judge עם פרומפט ומודל משלך; evaluator **מבוסס קוד** (Lambda function, לבדיקות שיש להן תשובה נכונה אחת); או evaluator מסוג **multi-dimension** שנותן ציון לעד 50 ממדים עם שם בקריאה אחת.',
          'Evaluators של **צד שלישי** מ-DeepEval ו-AutoEval.',
          'Evaluators מסוג **insight** כמו `Builtin.FailureAnalysis`, שמסבירים כישלונות במקום לתת ציון יחיד.'
        ] },
        { t: 'h', en: 'Three ways to run', he: 'שלוש דרכים להריץ' },
        { t: 'table', head: { en: ['Type', 'What it does', 'When'], he: ['סוג', 'מה הוא עושה', 'מתי'] }, rows: {
          en: [
            ['**[[Online evaluation]]**', 'Scores a sample of production sessions all the time. You create an *online evaluation configuration*: data source, evaluators (up to 25), sampling percentage, filters, an execution role.', 'Monitoring: is quality holding today?'],
            ['**[[On-demand evaluation]]**', 'You pass specific spans or traces (by ID) to the `Evaluate` API and get scores back at once. One evaluator per call.', 'Build-time tests, and investigating one bad conversation.'],
            ['**[[Batch evaluation]]**', 'An asynchronous job over many sessions stored in CloudWatch Logs (`CreateBatchEvaluation`). Supports ground truth. Gives aggregate and per-session results.', 'Comparing two versions on the same recorded sessions; regression runs.']
          ],
          he: [
            ['**[[Online evaluation]]**', 'נותן ציון לדגימה של סשני פרודקשן כל הזמן. יוצרים *online evaluation configuration*: מקור נתונים, evaluators (עד 25), אחוז דגימה, פילטרים, execution role.', 'ניטור: האם האיכות מחזיקה היום?'],
            ['**[[On-demand evaluation]]**', 'מעבירים spans או traces מסוימים (לפי ID) ל-API ‏`Evaluate` ומקבלים ציונים מיד. Evaluator אחד לכל קריאה.', 'בדיקות בזמן בנייה, וחקירה של שיחה גרועה אחת.'],
            ['**[[Batch evaluation]]**', 'Job אסינכרוני על הרבה סשנים ששמורים ב-CloudWatch Logs ‏(`CreateBatchEvaluation`). תומך ב-ground truth. נותן תוצאות מצטברות ותוצאות לכל סשן.', 'השוואה של שתי גרסאות על אותם סשנים מוקלטים; ריצות regression.']
          ] } },
        { t: 'quiz', q: { en: 'A customer sends a screenshot of a conversation where the agent booked the wrong hotel. You have the session ID. Which evaluation type helps you look into exactly this conversation right now?', he: 'לקוח שולח צילום מסך של שיחה שבה הסוכן הזמין מלון שגוי. יש לך את ה-session ID. איזה סוג evaluation עוזר לך לבדוק בדיוק את השיחה הזו עכשיו?' },
          options: { en: ['Online evaluation with a 100% sampling rate', 'A Bedrock automatic model evaluation job', 'On-demand evaluation of the traces of that session', 'An A/B test'], he: ['Online evaluation עם sampling rate של 100%', 'Automatic model evaluation job של Bedrock', 'On-demand evaluation של ה-traces של הסשן הזה', 'A/B test'] },
          answer: 2, explain: { en: 'On-demand evaluation takes the specific traces or spans you name and returns scores immediately, for example tool selection and tool parameter accuracy on the booking call. Online evaluation watches future traffic; it does not answer a question about one past session.', he: 'On-demand evaluation מקבל את ה-traces או ה-spans המסוימים שציינת ומחזיר ציונים מיד, למשל tool selection ו-tool parameter accuracy על קריאת ההזמנה. Online evaluation עוקב אחרי תעבורה עתידית; הוא לא עונה על שאלה לגבי סשן אחד מהעבר.' } },
        { t: 'h', en: 'Lab: turn on online evaluation from the CLI', he: 'מעבדה: להפעיל online evaluation מה-CLI' },
        { t: 'terminal', title: { en: 'Lab: online evaluation for a deployed agent', he: 'מעבדה: online evaluation לסוכן שכבר ב-deployment' },
          intro: { en: 'Your project has a runtime named `support_agent`. Use the AgentCore CLI. Type `hint` if you are stuck.', he: 'בפרויקט שלך יש runtime בשם `support_agent`. השתמש ב-AgentCore CLI. הקלד `hint` אם נתקעת.' },
          shell: 'bash — ~/support-agent',
          steps: [
            { ask: { en: 'Add an online evaluation named `support_quality` for the agent `support_agent`. Use the evaluators `Builtin.GoalSuccessRate` and `Builtin.Helpfulness`, the sampling rate `1.0` as in the docs example, and enable it on create. Flags: `--name`, `--agent`, `--evaluators`, `--sampling-rate`, `--enable-on-create true`.', he: 'הוסף online evaluation בשם `support_quality` לסוכן `support_agent`. השתמש ב-evaluators ‏`Builtin.GoalSuccessRate` ו-`Builtin.Helpfulness`, ב-sampling rate ‏`1.0` כמו בדוגמה בתיעוד, והפעל אותו ביצירה. דגלים: `--name`, ‏`--agent`, ‏`--evaluators`, ‏`--sampling-rate`, ‏`--enable-on-create true`.' },
              accept: ['^agentcore\\s+add\\s+online-eval\\b(?=.*--name\\s+\\S+)(?=.*--agent\\s+\\S+)(?=.*--evaluators\\s+.*Builtin\\.GoalSuccessRate)(?=.*Builtin\\.Helpfulness)(?=.*--sampling-rate\\s+\\S+)(?=.*--enable-on-create(\\s+true)?)'],
              hint: 'agentcore add online-eval --name "support_quality" --agent "support_agent" --evaluators "Builtin.GoalSuccessRate" "Builtin.Helpfulness" --sampling-rate 1.0 --enable-on-create true',
              output: 'Added online evaluation support_quality to the project.\nRun "agentcore deploy" to apply.', wrong: 'Use: agentcore add online-eval with --name, --agent, --evaluators (both IDs), --sampling-rate and --enable-on-create true.' },
            { ask: { en: 'The configuration exists only in your project files. Create it in AWS.', he: 'ההגדרה קיימת רק בקבצי הפרויקט שלך. צור אותה ב-AWS.' },
              accept: ['^agentcore\\s+deploy\\b'], hint: 'agentcore deploy', output: 'Deploying...\nOnline evaluation support_quality: created (ENABLED)\nDone.' },
            { ask: { en: 'Evaluations need traffic. Invoke the runtime `support_agent` once with the payload `{"prompt":"Where is my order 1234?"}`.', he: 'Evaluations צריכים תעבורה. הפעל את ה-runtime ‏`support_agent` פעם אחת עם ה-payload ‏`{"prompt":"Where is my order 1234?"}`.' },
              accept: ['^agentcore\\s+invoke\\b(?=.*--runtime\\s+\\S+)(?=.*--payload\\s+\\S+)'],
              hint: 'agentcore invoke --runtime support_agent --payload \'{"prompt":"Where is my order 1234?"}\'',
              output: 'Your order 1234 was shipped yesterday and should arrive in 2 days.', wrong: 'Use: agentcore invoke --runtime <name> --payload \'{"prompt":"..."}\'' },
            { ask: { en: 'Check that the request produced a trace: list the runtime traces of the last 30 minutes.', he: 'בדוק שהבקשה יצרה trace: הצג את ה-traces של ה-runtime מ-30 הדקות האחרונות.' },
              accept: ['^agentcore\\s+traces\\s+runtime\\s+list\\b(?=.*--since\\s+30m)'], hint: 'agentcore traces runtime list --since 30m',
              output: 'TRACE ID            STARTED     DURATION  SPANS\n6a1f...c20e         2 min ago   3.4s      7', wrong: 'Use: agentcore traces runtime list --since 30m' },
            { ask: { en: 'A load test is about to start and you do not want to pay for judging it. Pause the online evaluation. Its ID is `oe-1a2b3c`.', he: 'בדיקת עומס עומדת להתחיל ואתה לא רוצה לשלם על שיפוט שלה. השהה את ה-online evaluation. ה-ID שלו הוא `oe-1a2b3c`.' },
              accept: ['^agentcore\\s+eval\\s+online-eval\\s+pause\\b(?=.*--id\\s+\\S+)'], hint: 'agentcore eval online-eval pause --id oe-1a2b3c',
              output: 'Online evaluation oe-1a2b3c: DISABLED', wrong: 'Use: agentcore eval online-eval pause --id <ONLINE_EVAL_ID>' }
          ],
          done: { en: 'You created an online evaluation as code, sent traffic, checked that traces arrive, and paused it. The scores show up in CloudWatch a little after the sessions end.', he: 'יצרת online evaluation כקוד, שלחת תעבורה, בדקת ש-traces מגיעים, והשהית אותו. הציונים מופיעים ב-CloudWatch קצת אחרי שהסשנים מסתיימים.' } },
        { t: 'note', kind: 'warn', en: 'The CLI example in the docs uses `--sampling-rate 1.0`, while the console shows sampling as a percentage (0.01% to 100%, default 10%) and the API field is `samplingPercentage`. Before you rely on a number, check `agentcore add online-eval --help` for the unit. The CLI accepts up to 10 evaluators per configuration; the service limit is 25.', he: 'בדוגמת ה-CLI בתיעוד משתמשים ב-`--sampling-rate 1.0`, בעוד הקונסול מציג דגימה כאחוז (0.01% עד 100%, ברירת מחדל 10%) והשדה ב-API הוא `samplingPercentage`. לפני שאתה סומך על מספר, בדוק ב-`agentcore add online-eval --help` מה היחידה. ה-CLI מקבל עד 10 evaluators להגדרה; המגבלה של השירות היא 25.' },
        { t: 'h', en: 'The same thing with boto3', he: 'אותו דבר עם boto3' },
        { t: 'code', lang: 'python', code: 'client = boto3.client("bedrock-agentcore-control")\nclient.create_online_evaluation_config(\n    onlineEvaluationConfigName="strands_healthcare_agent_1",\n    rule={"samplingConfig": {"samplingPercentage": 80.0}},\n    dataSourceConfig={"cloudWatchLogs": {\n        "logGroupNames": ["/aws/agentcore/test-agent-traces"],\n        "serviceNames": ["strands_healthcare_single_agent.DEFAULT"]}},\n    evaluators=[{"evaluatorId": "Builtin.Helpfulness"}],\n    evaluationExecutionRoleArn=role_arn,\n    enableOnCreate=True,\n)', caption: { en: 'Here the data source is a CloudWatch log group plus a service name, which is how you evaluate an agent that runs outside AgentCore Runtime.', he: 'כאן מקור הנתונים הוא CloudWatch log group ועוד service name, וכך בודקים סוכן שרץ מחוץ ל-AgentCore Runtime.' } },
        { t: 'fill', prompt: { en: 'Create an online evaluation configuration that scores 20% of the sessions with the goal success evaluator.', he: 'צור online evaluation configuration שנותן ציון ל-20% מהסשנים עם ה-evaluator של goal success.' },
          lang: 'python', code: 'client = boto3.client("{{1}}")\nclient.{{2}}(\n    onlineEvaluationConfigName="support_quality",\n    rule={"samplingConfig": {"{{3}}": 20.0}},\n    dataSourceConfig=data_source,\n    evaluators=[{"evaluatorId": "{{4}}"}],\n    evaluationExecutionRoleArn=role_arn,\n    enableOnCreate=True,\n)', blanks: [
            { accept: ['bedrock-agentcore-control'], hint: { en: 'The AgentCore control-plane client', he: 'ה-client של ה-control plane של AgentCore' } },
            { accept: ['create_online_evaluation_config'], hint: { en: 'snake_case of CreateOnlineEvaluationConfig', he: 'snake_case של CreateOnlineEvaluationConfig' } },
            { accept: ['samplingPercentage'], hint: { en: 'camelCase: sampling + Percentage', he: 'camelCase: sampling + Percentage' } },
            { accept: ['Builtin.GoalSuccessRate'], hint: { en: 'Builtin. + GoalSuccessRate', he: 'Builtin. + GoalSuccessRate' } } ],
          explain: { en: 'Creating resources is always the control plane: `bedrock-agentcore-control`. The data plane client `bedrock-agentcore` is for invoking and, here, for on-demand scoring.', he: 'יצירת משאבים היא תמיד ב-control plane: ‏`bedrock-agentcore-control`. ה-client של ה-data plane ‏`bedrock-agentcore` משמש להפעלה, וכאן גם לציון לפי דרישה.' } },
        { t: 'h', en: 'The console screen', he: 'המסך בקונסול' },
        { t: 'console', service: 'Amazon Bedrock AgentCore', nav: ['#Resources', 'Gateways', 'Evaluations'], active: 'Evaluations',
          crumbs: ['Amazon Bedrock AgentCore', 'Evaluations', 'Create evaluation configuration'], heading: 'Create evaluation configuration',
          task: { en: 'Create an online evaluation configuration named `support_quality_prod` for an agent that runs on AgentCore Runtime. Score one session in four. Turn on the two evaluators that tell you whether users reach their goal and whether responses help. Let the console create the IAM role.', he: 'צור online evaluation configuration בשם `support_quality_prod` לסוכן שרץ על AgentCore Runtime. תן ציון לסשן אחד מכל ארבעה. הפעל את שני ה-evaluators שאומרים לך אם משתמשים מגיעים למטרה שלהם ואם התשובות עוזרות. תן לקונסול ליצור את ה-IAM role.' },
          panels: [
            { title: 'Evaluation details', fields: [
              { label: 'Evaluation name', type: 'input', value: '', expect: 'support_quality_prod', hint: { en: 'The brief gives the name: support_quality_prod', he: 'השם מופיע בתיאור המשימה: support_quality_prod' } },
              { label: 'Evaluation configuration description', type: 'input', value: '', placeholder: 'Optional' },
              { label: 'Session idle timeout', type: 'input', value: '15', help: '1 to 60 minutes', n: 1 } ] },
            { title: 'Data source', n: 2, fields: [
              { label: 'Data source', type: 'radio', options: ['Select a CloudWatch log group', 'Define with an agent endpoint'], value: 'Select a CloudWatch log group', expect: 'Define with an agent endpoint', hint: { en: 'The agent runs on AgentCore Runtime, so it has an agent endpoint.', he: 'הסוכן רץ על AgentCore Runtime, ולכן יש לו agent endpoint.' } } ] },
            { title: 'Evaluators', desc: 'Up to 25', n: 3, fields: [
              { label: 'Builtin.GoalSuccessRate', type: 'checkbox', value: false, expect: true, hint: { en: '"Do users reach their goal?" is the goal success rate, at session level.', he: '"האם משתמשים מגיעים למטרה?" זה goal success rate, ברמת הסשן.' } },
              { label: 'Builtin.Helpfulness', type: 'checkbox', value: false, expect: true, hint: { en: '"Do the responses help?" is helpfulness, at trace level.', he: '"האם התשובות עוזרות?" זה helpfulness, ברמת ה-trace.' } },
              { label: 'Builtin.SkillSelectionAccuracy', type: 'checkbox', value: false } ] },
            { title: 'Sampling', n: 4, fields: [
              { label: 'Sampling', type: 'input', value: '10', help: '0.01% - 100%', expect: ['25', '25%', '25.0'], hint: { en: 'One session in four is 25 percent.', he: 'סשן אחד מכל ארבעה הוא 25 אחוז.' } } ] },
            { title: 'Amazon Bedrock IAM role', fields: [
              { label: 'IAM role', type: 'radio', options: ['Use an existing role', 'Create a new role'], value: 'Use an existing role', expect: 'Create a new role', hint: { en: 'The brief says to let the console create the role.', he: 'בתיאור המשימה כתוב לתת לקונסול ליצור את ה-role.' } } ] }
          ],
          buttons: ['Cancel', 'Create evaluation configuration'],
          callouts: [
            { n: 1, en: 'A session is judged after it has been idle this long (default 15 minutes). This is why scores do not appear right away.', he: 'סשן נשפט אחרי שהוא היה לא פעיל במשך הזמן הזה (ברירת מחדל 15 דקות). לכן ציונים לא מופיעים מיד.' },
            { n: 2, en: 'An agent endpoint for agents on Runtime. A CloudWatch log group for agents that run anywhere else and send OpenTelemetry traces.', he: 'Agent endpoint לסוכנים על Runtime. ‏CloudWatch log group לסוכנים שרצים בכל מקום אחר ושולחים traces ב-OpenTelemetry.' },
            { n: 3, en: 'Each evaluator is a judge call on every sampled session, trace or tool call. More evaluators = more cost.', he: 'כל evaluator הוא קריאת judge על כל סשן, trace או קריאה לכלי שנדגמו. יותר evaluators = יותר עלות.' },
            { n: 4, en: 'The share of sessions that get scored. You can also add up to 5 filters to choose which sessions count.', he: 'החלק מהסשנים שמקבל ציון. אפשר גם להוסיף עד 5 פילטרים כדי לבחור אילו סשנים נכללים.' }
          ],
          success: { en: 'Created. New sessions are now sampled and scored. Look for the results in CloudWatch: GenAI Observability → Bedrock AgentCore → Agents → your agent and endpoint → the Evaluations tab.', he: 'נוצר. סשנים חדשים נדגמים עכשיו ומקבלים ציון. חפש את התוצאות ב-CloudWatch: ‏GenAI Observability ← Bedrock AgentCore ← Agents ← הסוכן וה-endpoint שלך ← הלשונית Evaluations.' },
          caption: { en: 'Simplified. Field names follow the docs (AgentCore console → Resources → Evaluations → Create evaluation configuration). The evaluator list is shown here as checkboxes, the panel titles "Evaluation details" and the label "IAM role" are ours, and the filters and the enable-after-create checkbox are left out.', he: 'מפושט. שמות השדות לפי התיעוד (קונסול AgentCore ← Resources ← Evaluations ← Create evaluation configuration). רשימת ה-evaluators מוצגת כאן כתיבות סימון, כותרת החלונית "Evaluation details" והתווית "IAM role" הן שלנו, והפילטרים ותיבת ההפעלה-אחרי-יצירה הושמטו.' } },
        { t: 'h', en: 'Where the results show up', he: 'איפה התוצאות מופיעות' },
        { t: 'list', en: [
          '**CloudWatch Logs**: the log group `/aws/bedrock-agentcore/evaluations/results/<online-evaluation-config-id>`. Each event has the evaluator name (`gen_ai.evaluation.name`), the score (`gen_ai.evaluation.score.value`), a label (`gen_ai.evaluation.score.label`) and an explanation, and it is linked to the original session, trace or span.',
          '**CloudWatch metrics**: the namespace `Bedrock-AgentCore/Evaluations`. Metrics mean you can put an alarm on a score.',
          '**CloudWatch console**: GenAI Observability → Bedrock AgentCore → Agents → pick the agent and endpoint → the **Evaluations** tab.'
        ], he: [
          '**CloudWatch Logs**: ה-log group ‏`/aws/bedrock-agentcore/evaluations/results/<online-evaluation-config-id>`. בכל אירוע יש את שם ה-evaluator ‏(`gen_ai.evaluation.name`), הציון (`gen_ai.evaluation.score.value`), תווית (`gen_ai.evaluation.score.label`) והסבר, והוא מקושר לסשן, ל-trace או ל-span המקוריים.',
          '**CloudWatch metrics**: ה-namespace ‏`Bedrock-AgentCore/Evaluations`. מטריקות פירושן שאפשר לשים alarm על ציון.',
          '**קונסול CloudWatch**: ‏GenAI Observability ← Bedrock AgentCore ← Agents ← בוחרים סוכן ו-endpoint ← הלשונית **Evaluations**.'
        ] },
        { t: 'quiz', q: { en: 'You created an online evaluation configuration ten minutes ago and sent five test conversations. The Evaluations tab is still empty. What is the most likely reason?', he: 'יצרת online evaluation configuration לפני עשר דקות ושלחת חמש שיחות בדיקה. הלשונית Evaluations עדיין ריקה. מה הסיבה הכי סבירה?' },
          options: { en: ['Evaluations work only on Bedrock Agents Classic', 'The sessions were not sampled, or have not passed the session idle timeout yet', 'Scores are written only to S3', 'Built-in evaluators must be trained first'], he: ['Evaluations עובדים רק על Bedrock Agents Classic', 'הסשנים לא נדגמו, או שעדיין לא עבר ה-session idle timeout', 'ציונים נכתבים רק ל-S3', 'Evaluators מובנים צריכים קודם אימון'] },
          answer: 1, explain: { en: 'With the default 10% sampling, five sessions will most likely not be picked at all. And a session is judged only after it has been idle for the timeout (default 15 minutes). For a test, use 100% sampling and wait. Also check that traces really arrive.', he: 'עם דגימה של 10% כברירת מחדל, חמישה סשנים כנראה בכלל לא ייבחרו. וסשן נשפט רק אחרי שהיה לא פעיל במשך ה-timeout (ברירת מחדל 15 דקות). לבדיקה, השתמש בדגימה של 100% וחכה. בדוק גם ש-traces באמת מגיעים.' } },
        { t: 'h', en: 'From measuring to improving: Optimization', he: 'ממדידה לשיפור: Optimization' },
        { t: 'p', en: 'AgentCore **Optimization** is the component that uses evaluation results to make the agent better. At overview level it has four parts:', he: 'AgentCore **Optimization** הוא הרכיב שמשתמש בתוצאות evaluation כדי לשפר את הסוכן. ברמת סקירה יש בו ארבעה חלקים:' },
        { t: 'list', en: [
          '**Recommendations**: the service reads traces and proposes an improved system prompt or better tool descriptions (API `StartRecommendation`).',
          '**Configuration bundles**: versioned configuration, so a prompt change is a new version that you can roll out and roll back.',
          '**[[Batch evaluation]]**: the job type you saw above.',
          '**[[A/B test]]ing** (API `CreateABTest`): the Gateway splits real traffic between the current version (control) and one new version (treatment). One test per gateway.',
          'There is also **Failure Insights**, in public preview in November 2026.'
        ], he: [
          '**Recommendations**: השירות קורא traces ומציע system prompt משופר או תיאורי כלים טובים יותר (API ‏`StartRecommendation`).',
          '**Configuration bundles**: הגדרות עם גרסאות, כך ששינוי פרומפט הוא גרסה חדשה שאפשר להפיץ ולהחזיר אחורה.',
          '**[[Batch evaluation]]**: סוג ה-job שראית למעלה.',
          '**[[A/B test]]ing** (API ‏`CreateABTest`): ה-Gateway מפצל תעבורה אמיתית בין הגרסה הנוכחית (control) לגרסה חדשה אחת (treatment). טסט אחד ל-gateway.',
          'יש גם **Failure Insights**, ב-public preview בנובמבר 2026.'
        ] },
        { t: 'quiz', q: { en: 'Optimization recommends a new system prompt. What is the professional way to adopt it?', he: 'Optimization ממליץ על system prompt חדש. מה הדרך המקצועית לאמץ אותו?' },
          options: { en: ['Deploy it to everyone at once, because AWS generated it', 'Ignore it, because generated prompts are never good', 'Run it against the golden dataset, then A/B test it on part of the traffic and compare the evaluation scores', 'Ask the agent whether it likes the new prompt'], he: ['לעשות deploy לכולם בבת אחת, כי AWS יצרה אותו', 'להתעלם, כי פרומפטים שנוצרו אוטומטית אף פעם לא טובים', 'להריץ אותו מול ה-golden dataset, ואז לעשות לו A/B test על חלק מהתעבורה ולהשוות את ציוני ה-evaluation', 'לשאול את הסוכן אם הוא אוהב את הפרומפט החדש'] },
          answer: 2, explain: { en: 'A recommendation is a candidate, not a fact. It goes through the same gate as any change: offline evaluation first, then a controlled comparison on real traffic.', he: 'המלצה היא מועמד, לא עובדה. היא עוברת את אותו שער כמו כל שינוי: קודם offline evaluation, ואז השוואה מבוקרת על תעבורה אמיתית.' } },
        { t: 'note', kind: 'info', en: 'Pricing model: built-in evaluators are billed per input and output token that the judge processes (the judge model is included). Custom evaluators are billed per evaluation, and the model you chose is billed in your account. Batch evaluation is cheaper than online. So the bill grows with sampling rate × number of evaluators × size of the traces.', he: 'מודל התמחור: evaluators מובנים מחויבים לפי טוקני קלט ופלט שה-judge מעבד (ה-judge model כלול). Evaluators מותאמים מחויבים לפי evaluation, והמודל שבחרת מחויב בחשבון שלך. Batch evaluation זול יותר מ-online. כלומר החשבון גדל עם sampling rate × מספר evaluators × גודל ה-traces.' },
        { t: 'reveal', q: { en: 'Interview question: "What is the difference between a Bedrock evaluation job and AgentCore Evaluations? When do you use each?"', he: 'שאלת ראיון: "מה ההבדל בין evaluation job של Bedrock לבין AgentCore Evaluations? מתי משתמשים בכל אחד?"' },
          a: { en: 'A Bedrock evaluation job is a batch job over a dataset file in S3. It evaluates a model or a RAG system on prompts I prepared, with algorithmic metrics, a judge model or humans. I use it before release: to choose a model, to check a knowledge base, to gate a prompt change. AgentCore Evaluations works on traces of a running agent. It understands sessions, turns and tool calls, so it can score goal success and tool selection, and it can run continuously on a sample of production traffic, on demand for specific traces, or as a batch over recorded sessions. I use it for agents and for monitoring. In a real project I use both: a golden dataset job in CI and online evaluation in production.', he: 'Evaluation job של Bedrock הוא job אצוותי על קובץ dataset ב-S3. הוא בודק מודל או מערכת RAG על פרומפטים שהכנתי, עם מטריקות אלגוריתמיות, judge model או אנשים. אני משתמש בו לפני שחרור: לבחור מודל, לבדוק knowledge base, לשים שער על שינוי פרומפט. AgentCore Evaluations עובד על traces של סוכן רץ. הוא מבין סשנים, תורות וקריאות לכלים, ולכן יכול לתת ציון ל-goal success ול-tool selection, והוא יכול לרוץ ברציפות על דגימה של תעבורת פרודקשן, לפי דרישה על traces מסוימים, או כ-batch על סשנים מוקלטים. אני משתמש בו לסוכנים ולניטור. בפרויקט אמיתי אני משתמש בשניהם: job על golden dataset ב-CI ו-online evaluation בפרודקשן.' } }
      ]
    },
    {
      id: 'm11l5', minutes: 13,
      title: { en: 'Building an evaluation habit', he: 'לבנות הרגל של evaluation' },
      blocks: [
        { t: 'p', en: 'Tools do not make quality. A habit does. Teams that ship good GenAI products all do the same boring things: they keep a golden dataset, they run it before every change, they check their judge, and they watch production. This lesson is that routine.', he: 'כלים לא יוצרים איכות. הרגל יוצר. צוותים שמשחררים מוצרי GenAI טובים עושים כולם את אותם דברים משעממים: הם מחזיקים golden dataset, מריצים אותו לפני כל שינוי, בודקים את ה-judge שלהם, ועוקבים אחרי פרודקשן. השיעור הזה הוא השגרה הזו.' },
        { t: 'h', en: '1. Write the golden dataset from real failures', he: '1. לכתוב את ה-golden dataset מכישלונות אמיתיים' },
        { t: 'list', en: [
          '**Start small.** 30 to 50 good cases this week are worth more than 1,000 cases "one day".',
          '**Take real questions**, from logs, support tickets and the people who know the customers. Invented questions are too clean.',
          '**Every production failure becomes a test case.** A customer got a wrong answer? Add the question with the right answer. The dataset becomes a memory of every mistake you ever fixed.',
          '**Cover the hard cases on purpose**: questions with two parts, questions whose answer is not in the documents (the right answer is "I do not know"), attacks, other languages, typos.',
          '**Label a category** on every case, so you see which area got worse.',
          '**Have a human approve every reference answer.** A wrong ground truth silently punishes correct answers.',
          '**Version the file** in git next to the prompts. A score means nothing if you do not know which dataset produced it.'
        ], he: [
          '**להתחיל בקטן.** 30 עד 50 מקרים טובים השבוע שווים יותר מ-1,000 מקרים "יום אחד".',
          '**לקחת שאלות אמיתיות**, מלוגים, מטיקטים של תמיכה ומהאנשים שמכירים את הלקוחות. שאלות מומצאות נקיות מדי.',
          '**כל כישלון בפרודקשן הופך למקרה בדיקה.** לקוח קיבל תשובה שגויה? מוסיפים את השאלה עם התשובה הנכונה. ה-dataset הופך לזיכרון של כל טעות שתיקנת אי פעם.',
          '**לכסות את המקרים הקשים בכוונה**: שאלות בשני חלקים, שאלות שהתשובה עליהן לא נמצאת במסמכים (התשובה הנכונה היא "אני לא יודע"), התקפות, שפות אחרות, שגיאות הקלדה.',
          '**לתייג קטגוריה** לכל מקרה, כדי לראות איזה תחום הורע.',
          '**שאדם יאשר כל תשובת ייחוס.** Ground truth שגוי מעניש בשקט תשובות נכונות.',
          '**לנהל גרסאות לקובץ** ב-git ליד הפרומפטים. ציון לא אומר כלום אם לא יודעים איזה dataset יצר אותו.'
        ] },
        { t: 'quiz', q: { en: 'Your golden dataset has 200 questions, and every one of them has an answer in the knowledge base. What important behaviour can you not measure?', he: 'ב-golden dataset שלך יש 200 שאלות, ולכל אחת מהן יש תשובה ב-knowledge base. איזו התנהגות חשובה אי אפשר למדוד?' },
          options: { en: ['Whether the bot answers fast', 'Whether the bot admits it does not know when the answer is not in the documents', 'Whether the bot answers correctly', 'Whether retrieval finds the right chunks'], he: ['האם הבוט עונה מהר', 'האם הבוט מודה שהוא לא יודע כשהתשובה לא נמצאת במסמכים', 'האם הבוט עונה נכון', 'האם האחזור מוצא את ה-chunks הנכונים'] },
          answer: 1, explain: { en: 'Hallucination happens mostly when the answer is missing. If the dataset has no such questions, your faithfulness score looks great and tells you nothing about the dangerous case. Add questions where the correct reference answer is a refusal.', he: 'Hallucination קורית בעיקר כשהתשובה חסרה. אם אין ב-dataset שאלות כאלה, ציון ה-faithfulness שלך נראה מצוין ולא אומר לך כלום על המקרה המסוכן. הוסף שאלות שבהן תשובת הייחוס הנכונה היא סירוב.' } },
        { t: 'h', en: '2. Evaluate in CI, before every change', he: '2. להריץ evaluation ב-CI, לפני כל שינוי' },
        { t: 'p', en: 'A prompt is code. A model ID is code. A chunk size is code. Any of them can break the product, so any change to them goes through the same gate in [[CI]]:', he: 'פרומפט הוא קוד. Model ID הוא קוד. גודל chunk הוא קוד. כל אחד מהם יכול לשבור את המוצר, ולכן כל שינוי בהם עובר את אותו שער ב-[[CI]]:' },
        { t: 'flow', steps: { en: ['Pull request changes a prompt, a model or a tool', 'CI runs the app on the golden dataset', 'A judge scores the answers (evaluation job or on-demand evaluation)', 'CI compares the scores with the baseline', 'A metric dropped more than the allowed margin? Block the merge', 'Otherwise merge, and the new scores become the baseline'], he: ['Pull request משנה פרומפט, מודל או כלי', 'CI מריץ את האפליקציה על ה-golden dataset', 'Judge נותן ציון לתשובות (evaluation job או on-demand evaluation)', 'CI משווה את הציונים ל-baseline', 'מטריקה ירדה יותר מהמרווח המותר? חוסמים את ה-merge', 'אחרת ממזגים, והציונים החדשים הופכים ל-baseline'] }, caption: { en: 'The evaluation gate.', he: 'שער ה-evaluation.' } },
        { t: 'list', en: [
          '**Compare with the baseline, not with a fixed number.** "Faithfulness may not drop by more than 0.03" is a better rule than "faithfulness must be above 0.9".',
          '**Allow a margin for noise.** Models and judges are [[Non-deterministic]]. Run the same version twice and see how much the score moves by itself. A difference smaller than that is not a result.',
          '**Look at the per-category scores and at the worst examples**, not only at the average.',
          '**Keep it fast enough to run.** A small "smoke" subset on every pull request and the full dataset every night is a common split.'
        ], he: [
          '**להשוות ל-baseline, לא למספר קבוע.** "Faithfulness לא יכול לרדת ביותר מ-0.03" הוא כלל טוב יותר מ-"faithfulness חייב להיות מעל 0.9".',
          '**להשאיר מרווח לרעש.** מודלים ו-judges הם [[Non-deterministic]]. הרץ את אותה גרסה פעמיים וראה כמה הציון זז מעצמו. הבדל קטן מזה הוא לא תוצאה.',
          '**להסתכל על הציונים לפי קטגוריה ועל הדוגמאות הגרועות ביותר**, לא רק על הממוצע.',
          '**לשמור את זה מהיר מספיק כדי שירוץ.** תת-קבוצה קטנה ("smoke") בכל pull request וה-dataset המלא כל לילה הם חלוקה נפוצה.'
        ] },
        { t: 'quiz', q: { en: 'The same app version, evaluated twice on the same dataset, scores 0.86 and 0.88 on helpfulness. A pull request then scores 0.87. What do you conclude?', he: 'אותה גרסת אפליקציה, שנבדקה פעמיים על אותו dataset, מקבלת 0.86 ו-0.88 ב-helpfulness. ‏Pull request מקבל אחר כך 0.87. מה המסקנה?' },
          options: { en: ['The pull request improved helpfulness by 0.01', 'The pull request made helpfulness worse by 0.01', 'The judge is broken', 'No measurable change: the difference is inside the noise'], he: ['ה-pull request שיפר את ה-helpfulness ב-0.01', 'ה-pull request הרע את ה-helpfulness ב-0.01', 'ה-judge שבור', 'אין שינוי מדיד: ההבדל נמצא בתוך הרעש'] },
          answer: 3, explain: { en: 'The score moves by about 0.02 with no change at all. 0.87 sits inside that band. To see small effects you need more test cases, repeated runs, or a more stable metric.', he: 'הציון זז בערך ב-0.02 בלי שום שינוי. 0.87 נמצא בתוך הטווח הזה. כדי לראות השפעות קטנות צריך יותר מקרי בדיקה, ריצות חוזרות, או מטריקה יציבה יותר.' } },
        { t: 'h', en: '3. Judge the judge', he: '3. לשפוט את ה-judge' },
        { t: 'p', en: 'An LLM judge is a model too. It can be too generous, it can prefer long answers, it can misread your rubric. If you never check it, you are steering by an instrument that nobody calibrated.', he: 'LLM judge הוא גם מודל. הוא יכול להיות נדיב מדי, להעדיף תשובות ארוכות, לקרוא לא נכון את ה-rubric שלך. אם אף פעם לא בודקים אותו, מנווטים לפי מכשיר שאף אחד לא כייל.' },
        { t: 'list', ordered: true, en: [
          'Take a sample of 30 to 50 judged answers, with good and bad ones in it.',
          'Have a human score the same answers **without seeing the judge scores**.',
          'Compare. Where they disagree, read the judge\'s explanation: it usually shows what the judge misunderstood.',
          'Fix the judge prompt or the [[Rating scale]] (clearer definitions, a smaller scale), and compare again.',
          'Repeat the check whenever you change the judge model or the judge prompt.'
        ], he: [
          'לוקחים דגימה של 30 עד 50 תשובות שנשפטו, עם טובות וגרועות בתוכה.',
          'אדם נותן ציון לאותן תשובות **בלי לראות את ציוני ה-judge**.',
          'משווים. איפה שהם לא מסכימים, קוראים את ההסבר של ה-judge: בדרך כלל הוא מראה מה ה-judge לא הבין.',
          'מתקנים את פרומפט ה-judge או את ה-[[Rating scale]] (הגדרות ברורות יותר, סולם קטן יותר), ומשווים שוב.',
          'חוזרים על הבדיקה בכל פעם שמשנים את ה-judge model או את פרומפט ה-judge.'
        ] },
        { t: 'note', kind: 'warn', en: '**Keep the judge fixed.** If you change the generator model and the judge model in the same week, you cannot tell which one moved the score. Old scores and new scores are comparable only when the judge, its prompt and the dataset are the same. When you must change the judge, re-score the baseline with the new judge first.', he: '**לשמור את ה-judge קבוע.** אם משנים את ה-generator model ואת ה-judge model באותו שבוע, אי אפשר לדעת מי מהם הזיז את הציון. ציונים ישנים וחדשים ניתנים להשוואה רק כשה-judge, הפרומפט שלו וה-dataset זהים. כשחייבים להחליף judge, קודם נותנים ציון מחדש ל-baseline עם ה-judge החדש.' },
        { t: 'h', en: '4. Sample production traffic', he: '4. לדגום תעבורת פרודקשן' },
        { t: 'p', en: 'The golden dataset shows what you thought of. Production shows the rest. Turn on [[Online evaluation]] with a [[Sampling rate]] you can afford, put an alarm on the scores that matter, and every week read the lowest-scored sessions. The interesting ones go into the golden dataset. This closes the loop.', he: 'ה-golden dataset מראה את מה שחשבת עליו. פרודקשן מראה את השאר. מפעילים [[Online evaluation]] עם [[Sampling rate]] שאפשר לעמוד בו, שמים alarm על הציונים שחשובים, וכל שבוע קוראים את הסשנים עם הציון הנמוך ביותר. המעניינים נכנסים ל-golden dataset. כך סוגרים את המעגל.' },
        { t: 'flow', steps: { en: ['Golden dataset', 'CI gate before release', 'Production', 'Online evaluation on a sample', 'Read the worst sessions', 'Add them to the golden dataset'], he: ['Golden dataset', 'שער CI לפני שחרור', 'פרודקשן', 'Online evaluation על דגימה', 'קוראים את הסשנים הגרועים ביותר', 'מוסיפים אותם ל-golden dataset'] }, caption: { en: 'The evaluation loop. The last step feeds the first.', he: 'מעגל ה-evaluation. הצעד האחרון מזין את הראשון.' } },
        { t: 'h', en: '5. Know what evaluation costs', he: '5. לדעת כמה evaluation עולה' },
        { t: 'p', en: 'A judge reads the question, the context and the answer, then writes a score and an explanation. That can be more tokens than the original answer cost. The cost is roughly: **number of answers × number of metrics × tokens per judgment**. The knobs:', he: 'Judge קורא את השאלה, את ההקשר ואת התשובה, ואז כותב ציון והסבר. זה יכול להיות יותר טוקנים ממה שעלתה התשובה המקורית. העלות היא בערך: **מספר התשובות × מספר המטריקות × טוקנים לכל שיפוט**. הכפתורים:' },
        { t: 'list', en: ['Sample: 5 to 10 percent of production traffic is usually enough to see a trend.', 'Use few metrics, the ones you will act on.', 'Use cheap checks where they are enough: a code-based evaluator for "is the JSON valid" costs almost nothing.', 'Use batch evaluation for work that does not need an answer right away.', 'Pause online evaluation during load tests.'], he: ['לדגום: 5 עד 10 אחוז מתעבורת הפרודקשן בדרך כלל מספיקים כדי לראות מגמה.', 'להשתמש במעט מטריקות, אלה שתפעל לפיהן.', 'להשתמש בבדיקות זולות איפה שהן מספיקות: evaluator מבוסס קוד ל-"האם ה-JSON תקין" עולה כמעט כלום.', 'להשתמש ב-batch evaluation לעבודה שלא צריכה תשובה מיד.', 'להשהות online evaluation בזמן בדיקות עומס.'] },
        { t: 'quiz', q: { en: 'An agent handles 100,000 sessions a day. Online evaluation runs 12 evaluators on 100% of them, and the evaluation bill is now higher than the model bill. What is the most sensible first change?', he: 'סוכן מטפל ב-100,000 סשנים ביום. Online evaluation מריץ 12 evaluators על 100% מהם, וחשבון ה-evaluation גבוה עכשיו מחשבון המודל. מה השינוי הראשון הכי הגיוני?' },
          options: { en: ['Lower the sampling rate and keep only the evaluators you act on', 'Turn evaluation off', 'Switch the agent to a smaller model', 'Delete the golden dataset'], he: ['להוריד את ה-sampling rate ולהשאיר רק את ה-evaluators שפועלים לפיהם', 'לכבות את ה-evaluation', 'להעביר את הסוכן למודל קטן יותר', 'למחוק את ה-golden dataset'] },
          answer: 0, explain: { en: 'A trend is visible on a few percent of 100,000 sessions. Twelve evaluators on everything is paying to measure the same thing a hundred thousand times. Turning evaluation off saves money until the first silent regression.', he: 'מגמה נראית על כמה אחוזים מתוך 100,000 סשנים. שנים-עשר evaluators על הכול זה לשלם כדי למדוד את אותו דבר מאה אלף פעם. לכבות את ה-evaluation חוסך כסף עד ה-regression השקט הראשון.' } },
        { t: 'h', en: 'Worked example: "we changed the model and quality dropped"', he: 'דוגמה מלאה: "החלפנו מודל והאיכות ירדה"' },
        { t: 'p', en: 'On Monday the team moved the support agent to a newer, cheaper model. On Thursday the support lead says: "The bot got worse." How do you find out whether that is true, and prove it?', he: 'ביום שני הצוות העביר את סוכן התמיכה למודל חדש וזול יותר. ביום חמישי ראש צוות התמיכה אומר: "הבוט נהיה גרוע יותר." איך מגלים אם זה נכון, ומוכיחים את זה?' },
        { t: 'list', ordered: true, en: [
          '**Look at production first.** Open the online evaluation scores and compare the days before Monday with the days after. Suppose goal success rate went from 0.81 to 0.72 on the day of the switch. Now it is a measurement with a date on it, not an opinion.',
          '**Reproduce it offline, changing only one thing.** Run the golden dataset twice with the same prompts, the same tools and the same judge: once with the old model, once with the new one.',
          '**Compare per metric and per category** (table below).',
          '**Read the worst examples and the judge explanations.** In this story the new model often answers from its own knowledge instead of from the retrieved documents, mostly in the "Billing" category.',
          '**Form one hypothesis and test it.** The prompt was tuned for the old model. You make the grounding instruction more explicit and run the dataset again.',
          '**Decide with numbers.** If the fixed prompt brings the scores back to the baseline, ship it through the normal gate. If not, roll the model back. Both are fine. Staying in an unmeasured state is not.',
          '**Leave the system stronger.** Add the Billing failures to the golden dataset, and make "run the golden dataset" a required step for every model change.'
        ], he: [
          '**קודם מסתכלים על פרודקשן.** פותחים את ציוני ה-online evaluation ומשווים את הימים שלפני יום שני לימים שאחריו. נניח ש-goal success rate ירד מ-0.81 ל-0.72 ביום ההחלפה. עכשיו זו מדידה עם תאריך, לא דעה.',
          '**משחזרים offline, ומשנים רק דבר אחד.** מריצים את ה-golden dataset פעמיים עם אותם פרומפטים, אותם כלים ואותו judge: פעם עם המודל הישן, פעם עם החדש.',
          '**משווים לפי מטריקה ולפי קטגוריה** (הטבלה למטה).',
          '**קוראים את הדוגמאות הגרועות ביותר ואת ההסברים של ה-judge.** בסיפור הזה המודל החדש עונה לעיתים קרובות מהידע שלו במקום מהמסמכים שאוחזרו, בעיקר בקטגוריית "Billing".',
          '**מנסחים השערה אחת ובודקים אותה.** הפרומפט כוונן למודל הישן. הופכים את הוראת ה-grounding למפורשת יותר ומריצים את ה-dataset שוב.',
          '**מחליטים עם מספרים.** אם הפרומפט המתוקן מחזיר את הציונים ל-baseline, משחררים אותו דרך השער הרגיל. אם לא, מחזירים את המודל הישן. שתי האפשרויות בסדר. להישאר במצב לא מדוד זה לא בסדר.',
          '**משאירים את המערכת חזקה יותר.** מוסיפים את הכישלונות של Billing ל-golden dataset, והופכים את "להריץ את ה-golden dataset" לשלב חובה בכל החלפת מודל.'
        ] },
        { t: 'table', head: { en: ['Metric (golden dataset, 180 cases)', 'Old model', 'New model', 'New model + fixed prompt'], he: ['מטריקה (golden dataset, ‏180 מקרים)', 'מודל ישן', 'מודל חדש', 'מודל חדש + פרומפט מתוקן'] }, rows: {
          en: [['Correctness', '0.88', '0.79', '0.87'], ['Faithfulness', '0.93', '0.74', '0.92'], ['Completeness', '0.84', '0.85', '0.85'], ['Helpfulness', '0.86', '0.87', '0.87'], ['Faithfulness, category "Billing" only', '0.91', '0.52', '0.90']],
          he: [['Correctness', '0.88', '0.79', '0.87'], ['Faithfulness', '0.93', '0.74', '0.92'], ['Completeness', '0.84', '0.85', '0.85'], ['Helpfulness', '0.86', '0.87', '0.87'], ['Faithfulness, רק קטגוריית "Billing"', '0.91', '0.52', '0.90']] } },
        { t: 'quiz', q: { en: 'Look at the table. Which sentence is the best summary for your manager?', he: 'הסתכל על הטבלה. איזה משפט הוא הסיכום הטוב ביותר למנהל שלך?' },
          options: { en: ['"The new model is worse at everything."', '"Nothing changed; the complaints are subjective."', '"The new model writes equally helpful and complete answers, but it stopped sticking to our documents, mainly in Billing. A prompt fix restores that."', '"The judge model is unreliable, so we cannot know."'], he: ['"המודל החדש גרוע יותר בכל דבר."', '"שום דבר לא השתנה; התלונות סובייקטיביות."', '"המודל החדש כותב תשובות מועילות ושלמות באותה מידה, אבל הוא הפסיק להיצמד למסמכים שלנו, בעיקר ב-Billing. תיקון פרומפט מחזיר את זה."', '"ה-judge model לא אמין, אז אי אפשר לדעת."'] },
          answer: 2, explain: { en: 'Completeness and helpfulness did not move (0.01 is noise). Faithfulness fell hard, and correctness fell with it. The category split shows where. This is why you track several metrics and categories: one "quality" number would have said "a bit worse" and nothing more.', he: 'Completeness ו-helpfulness לא זזו (0.01 זה רעש). Faithfulness צנח, ו-correctness ירד איתו. הפיצול לפי קטגוריה מראה איפה. בגלל זה עוקבים אחרי כמה מטריקות וקטגוריות: מספר "איכות" אחד היה אומר "קצת יותר גרוע" ותו לא.' } },
        { t: 'order', prompt: { en: 'A user reports that quality dropped after a release. Put your investigation in order.', he: 'משתמש מדווח שהאיכות ירדה אחרי שחרור. סדר את החקירה שלך.' }, items: {
          en: ['Check the online evaluation scores before and after the release date', 'Run the golden dataset on the old and the new version with the same judge', 'Compare scores per metric and per category', 'Read the lowest-scored examples and the judge explanations', 'Fix or roll back, and run the dataset again', 'Add the new failures to the golden dataset'],
          he: ['לבדוק את ציוני ה-online evaluation לפני ואחרי תאריך השחרור', 'להריץ את ה-golden dataset על הגרסה הישנה והחדשה עם אותו judge', 'להשוות ציונים לפי מטריקה ולפי קטגוריה', 'לקרוא את הדוגמאות עם הציון הנמוך ביותר ואת ההסברים של ה-judge', 'לתקן או להחזיר אחורה, ולהריץ את ה-dataset שוב', 'להוסיף את הכישלונות החדשים ל-golden dataset'] },
          explain: { en: 'Confirm, reproduce, locate, understand, fix, remember.', he: 'לאשר, לשחזר, לאתר, להבין, לתקן, לזכור.' } },
        { t: 'reveal', q: { en: 'Interview question: "How do you know your LLM judge can be trusted?"', he: 'שאלת ראיון: "איך אתה יודע שאפשר לסמוך על ה-LLM judge שלך?"' },
          a: { en: 'I do not assume it. I calibrate it against people. I take a few dozen answers, have a human rate them blind, and compare with the judge. Where they disagree I read the judge\'s explanation and usually find an unclear rubric, so I tighten the definitions and use a small scale such as 0/1 or 1 to 3. I judge one quality per metric, never "overall quality". I keep the judge model and prompt fixed between runs so that scores stay comparable, and I repeat the calibration when either changes. And for anything with one right answer, such as "was the right tool called", I use code, not a judge.', he: 'אני לא מניח את זה. אני מכייל אותו מול אנשים. אני לוקח כמה עשרות תשובות, נותן לאדם לדרג אותן בעיוורון, ומשווה ל-judge. איפה שהם לא מסכימים אני קורא את ההסבר של ה-judge ובדרך כלל מוצא rubric לא ברור, אז אני מחדד את ההגדרות ומשתמש בסולם קטן כמו 0/1 או 1 עד 3. אני שופט איכות אחת לכל מטריקה, אף פעם לא "איכות כללית". אני שומר את ה-judge model ואת הפרומפט קבועים בין ריצות כדי שהציונים יישארו ניתנים להשוואה, וחוזר על הכיול כשאחד מהם משתנה. ולכל דבר שיש לו תשובה נכונה אחת, כמו "האם נקרא הכלי הנכון", אני משתמש בקוד, לא ב-judge.' } }
      ]
    },
    {
      id: 'm11l6', minutes: 10,
      title: { en: 'Jargon and scenarios workout', he: 'אימון ז׳רגון ותרחישים' },
      blocks: [
        { t: 'p', en: 'Evaluation has more jargon than any other part of GenAI, and people mix the words up all the time. This workout makes sure you do not.', he: 'ב-evaluation יש יותר ז׳רגון מבכל חלק אחר של GenAI, ואנשים מתבלבלים במילים כל הזמן. האימון הזה מוודא שאתה לא.' },
        { t: 'match', prompt: { en: 'Match the word to its meaning.', he: 'התאם את המילה למשמעות שלה.' }, pairs: [
          { a: 'LLM-as-a-judge', b: { en: 'A second model scores the answers', he: 'מודל שני נותן ציון לתשובות' } },
          { a: 'Bring your own inference', b: { en: 'The job only scores answers you already produced', he: 'ה-job רק נותן ציון לתשובות שכבר יצרת' } },
          { a: 'Retrieve only', b: { en: 'A RAG job that evaluates just the search', he: 'RAG job שבודק רק את החיפוש' } },
          { a: 'Sampling rate', b: { en: 'The share of production sessions that get scored', he: 'החלק מסשני הפרודקשן שמקבל ציון' } },
          { a: 'Custom metric', b: { en: 'Your own judge prompt and rating scale', he: 'פרומפט judge וסולם דירוג משלך' } },
          { a: 'Regression', b: { en: 'A score that got worse after a change', he: 'ציון שהורע אחרי שינוי' } }
        ] },
        { t: 'match', prompt: { en: 'Match the need to the AWS tool.', he: 'התאם את הצורך לכלי של AWS.' }, pairs: [
          { a: { en: 'Compare two foundation models on summarization with reference summaries', he: 'להשוות שני foundation models בסיכום עם סיכומי ייחוס' }, b: { en: 'Bedrock automatic (programmatic) model evaluation', he: 'Bedrock automatic (programmatic) model evaluation' } },
          { a: { en: 'Check whether a new chunking strategy finds better passages', he: 'לבדוק אם אסטרטגיית chunking חדשה מוצאת קטעים טובים יותר' }, b: { en: 'Bedrock RAG evaluation, retrieve only', he: 'Bedrock RAG evaluation, ‏retrieve only' } },
          { a: { en: 'Watch the quality of a production agent every day', he: 'לעקוב אחרי האיכות של סוכן בפרודקשן כל יום' }, b: { en: 'AgentCore online evaluation', he: 'AgentCore online evaluation' } },
          { a: { en: 'Score one suspicious conversation right now', he: 'לתת ציון לשיחה חשודה אחת עכשיו' }, b: { en: 'AgentCore on-demand evaluation', he: 'AgentCore on-demand evaluation' } },
          { a: { en: 'Try a new prompt on part of the real traffic', he: 'לנסות פרומפט חדש על חלק מהתעבורה האמיתית' }, b: { en: 'AgentCore Optimization A/B test', he: 'AgentCore Optimization A/B test' } }
        ] },
        { t: 'quiz', q: { en: 'A RAG evaluation shows: context relevance 0.90, context coverage 0.88, faithfulness 0.55. What do you fix?', he: 'RAG evaluation מראה: context relevance ‏0.90, ‏context coverage ‏0.88, ‏faithfulness ‏0.55. מה מתקנים?' },
          options: { en: ['The generation step: prompt, model or temperature. Retrieval is fine', 'The chunking strategy', 'The embedding model', 'The number of retrieved results'], he: ['את שלב היצירה: פרומפט, מודל או temperature. האחזור בסדר', 'את אסטרטגיית ה-chunking', 'את מודל ה-embedding', 'את מספר התוצאות שמאוחזרות'] },
          answer: 0, explain: { en: 'Retrieval brings the right text (both context scores are high), but the answer does not stick to it. The other three options all change retrieval, which is not the broken part.', he: 'האחזור מביא את הטקסט הנכון (שני ציוני ה-context גבוהים), אבל התשובה לא נצמדת אליו. שלוש האפשרויות האחרות כולן משנות את האחזור, שהוא לא החלק השבור.' } },
        { t: 'quiz', q: { en: 'Your job fails at the start with a dataset validation error. The file has lines like {"prompt": "...", "referenceResponse": "..."} and the job type is a RAG retrieve-and-generate evaluation. What is wrong?', he: 'ה-job שלך נכשל בהתחלה עם שגיאת ולידציה של ה-dataset. בקובץ יש שורות כמו {"prompt": "...", "referenceResponse": "..."} וסוג ה-job הוא RAG evaluation מסוג retrieve-and-generate. מה לא בסדר?' },
          options: { en: ['JSONL files are not supported', 'The file needs at least 1,000 lines', 'The S3 bucket must be public', 'RAG evaluation expects the conversationTurns format, with referenceResponses'], he: ['קובצי JSONL לא נתמכים', 'הקובץ צריך לפחות 1,000 שורות', 'ה-S3 bucket חייב להיות ציבורי', 'RAG evaluation מצפה לפורמט conversationTurns, עם referenceResponses'] },
          answer: 3, explain: { en: 'The flat `prompt` / `referenceResponse` format belongs to model evaluation. RAG jobs use `conversationTurns`. 1,000 is the maximum number of prompts, not the minimum, and a bucket never has to be public.', he: 'הפורמט השטוח `prompt` / ‏`referenceResponse` שייך ל-model evaluation. ‏RAG jobs משתמשים ב-`conversationTurns`. ‏1,000 הוא המספר המקסימלי של פרומפטים, לא המינימלי, ו-bucket אף פעם לא חייב להיות ציבורי.' } },
        { t: 'quiz', q: { en: 'A teammate proposes one custom metric: "Rate the overall quality of the answer from 1 to 10." Why is this a weak metric?', he: 'חבר צוות מציע custom metric אחד: "Rate the overall quality of the answer from 1 to 10." למה זו מטריקה חלשה?' },
          options: { en: ['Custom metrics cannot use numbers', 'It mixes many qualities into one number, the scale points are not defined, and a low score does not tell you what to fix', 'Judges can only answer yes or no', 'It needs ground truth'], he: ['Custom metrics לא יכולים להשתמש במספרים', 'היא מערבבת הרבה איכויות למספר אחד, נקודות הסולם לא מוגדרות, וציון נמוך לא אומר לך מה לתקן', 'Judges יכולים לענות רק כן או לא', 'היא דורשת ground truth'] },
          answer: 1, explain: { en: 'What is the difference between a 6 and a 7? Nobody knows, including the judge, so scores drift. Split it into separate metrics (correct? complete? grounded?), each with a small, defined scale.', he: 'מה ההבדל בין 6 ל-7? אף אחד לא יודע, כולל ה-judge, ולכן הציונים נודדים. מפצלים למטריקות נפרדות (נכון? שלם? מבוסס?), כל אחת עם סולם קטן ומוגדר.' } },
        { t: 'quiz', q: { en: 'An agent has tool selection accuracy 0.97 and tool parameter accuracy 0.61. What is the most useful next step?', he: 'לסוכן יש tool selection accuracy של 0.97 ו-tool parameter accuracy של 0.61. מה הצעד הבא הכי מועיל?' },
          options: { en: ['Add more tools', 'Rewrite the tool names', 'Improve the descriptions of the tool parameters and their schema, and look at the failing calls', 'Raise the sampling rate'], he: ['להוסיף עוד כלים', 'לכתוב מחדש את שמות הכלים', 'לשפר את התיאורים של הפרמטרים של הכלים ואת ה-schema שלהם, ולהסתכל על הקריאות שנכשלו', 'להעלות את ה-sampling rate'] },
          answer: 2, explain: { en: 'The agent picks the right tool but fills in the arguments badly. That points at the parameter descriptions and the input schema (formats, required fields, examples), not at the choice of tool.', he: 'הסוכן בוחר את הכלי הנכון אבל ממלא את הארגומנטים רע. זה מצביע על תיאורי הפרמטרים ועל ה-input schema (פורמטים, שדות חובה, דוגמאות), לא על בחירת הכלי.' } },
        { t: 'quiz', q: { en: 'Which statements about evaluation are true? Pick all that apply.', he: 'אילו משפטים על evaluation נכונים? בחר את כל הנכונים.' },
          options: { en: ['Scores from two runs are comparable only if the judge and the dataset are the same', 'A judge model returns an explanation with the score', 'Online evaluation replaces the golden dataset', 'A high average can hide a weak category'], he: ['ציונים משתי ריצות ניתנים להשוואה רק אם ה-judge וה-dataset זהים', 'Judge model מחזיר הסבר יחד עם הציון', 'Online evaluation מחליף את ה-golden dataset', 'ממוצע גבוה יכול להסתיר קטגוריה חלשה'] },
          answer: [0, 1, 3], explain: { en: 'Online and offline evaluation do different jobs: offline protects a release, online watches reality. You need both, and failures found online go back into the golden dataset.', he: 'Online ו-offline evaluation עושים עבודות שונות: offline מגן על שחרור, online עוקב אחרי המציאות. צריך את שניהם, וכישלונות שנמצאו online חוזרים ל-golden dataset.' } },
        { t: 'reveal', q: { en: 'Interview question: "You join a team that has a RAG chatbot in production and no evaluations at all. What do you do in your first two weeks?"', he: 'שאלת ראיון: "אתה מצטרף לצוות שיש לו צ׳אטבוט RAG בפרודקשן ואין לו שום evaluations. מה אתה עושה בשבועיים הראשונים?"' },
          a: { en: 'Week one: build a first golden dataset of 40 to 50 cases from real logs and support tickets, with reference answers approved by someone who knows the product, a category on each, and some questions whose answer is not in the documents. Run it through the current system to get a baseline for three or four metrics: correctness, faithfulness, completeness and context coverage. Read the worst cases; that alone usually finds two or three real bugs. Week two: put the run into CI so that every prompt, model or retrieval change is compared with the baseline, and turn on sampled online evaluation with an alarm. Calibrate the judge on a small human-labelled sample. From then on every production failure becomes a new test case.', he: 'שבוע ראשון: לבנות golden dataset ראשון של 40 עד 50 מקרים מלוגים אמיתיים ומטיקטים של תמיכה, עם תשובות ייחוס שאושרו על ידי מישהו שמכיר את המוצר, קטגוריה לכל אחד, וכמה שאלות שהתשובה עליהן לא נמצאת במסמכים. להריץ אותו דרך המערכת הנוכחית כדי לקבל baseline לשלוש או ארבע מטריקות: correctness, ‏faithfulness, ‏completeness ו-context coverage. לקרוא את המקרים הגרועים ביותר; זה לבד בדרך כלל מוצא שניים או שלושה באגים אמיתיים. שבוע שני: להכניס את הריצה ל-CI כך שכל שינוי בפרומפט, במודל או באחזור מושווה ל-baseline, ולהפעיל online evaluation על דגימה עם alarm. לכייל את ה-judge על דגימה קטנה שאדם תייג. מכאן והלאה כל כישלון בפרודקשן הופך למקרה בדיקה חדש.' } },
        { t: 'reveal', q: { en: 'Interview question: "Evaluation scores are all above 0.9, but users are unhappy. What could be going on?"', he: 'שאלת ראיון: "ציוני ה-evaluation כולם מעל 0.9, אבל המשתמשים לא מרוצים. מה יכול לקרות?"' },
          a: { en: 'Several things, and I would check them in this order. The dataset may not look like real traffic: clean questions, no hard cases, no missing-answer cases. The metrics may measure the wrong thing: tone and coherence are high while nobody measures goal success or correctness against ground truth. The judge may be too generous, which a blind human check on a sample will show. The averages may hide a weak category or a weak language. And the problem may not be answer quality at all: latency, a confusing UI, or too many guardrail refusals. So I would sample real sessions with low user satisfaction, read them, and let them tell me which of these it is.', he: 'כמה דברים, והייתי בודק אותם בסדר הזה. ה-dataset אולי לא דומה לתעבורה אמיתית: שאלות נקיות, בלי מקרים קשים, בלי מקרים של תשובה חסרה. המטריקות אולי מודדות את הדבר הלא נכון: טון ו-coherence גבוהים בזמן שאף אחד לא מודד goal success או correctness מול ground truth. ה-judge אולי נדיב מדי, ובדיקה אנושית עיוורת על דגימה תראה את זה. הממוצעים אולי מסתירים קטגוריה חלשה או שפה חלשה. והבעיה אולי בכלל לא איכות התשובה: latency, ממשק מבלבל, או יותר מדי סירובים של guardrail. אז הייתי דוגם סשנים אמיתיים עם שביעות רצון נמוכה, קורא אותם, ונותן להם להגיד לי איזה מאלה זה.' } },
        { t: 'task', title: { en: 'Do it for real (after you land)', he: 'עשה את זה באמת (אחרי הנחיתה)' }, steps: {
          en: ['Write a JSONL file with 20 real questions for an app you know, each with `prompt`, `referenceResponse` and `category`. Add three questions that have no answer in your documents.', 'Upload it to S3 and create a Bedrock "Automatic: Model as a judge" evaluation with Correctness and Completeness. Read the explanations of the three lowest scores.', 'Run your own app on the same questions, add `modelResponses` to the file, and run the job again with "Bring your own inference responses".', 'If you have a knowledge base: run a retrieve-only RAG evaluation and look at Context relevance and Context coverage.', 'If you have an agent on AgentCore Runtime: run `agentcore add online-eval` with `Builtin.GoalSuccessRate` and `Builtin.Helpfulness`, deploy, send a few conversations, and find the scores in the CloudWatch Evaluations tab.', 'Score ten answers yourself without looking at the judge, and compare.', 'Stop or delete what you created, so that it does not keep costing money.'],
          he: ['כתוב קובץ JSONL עם 20 שאלות אמיתיות לאפליקציה שאתה מכיר, כל אחת עם `prompt`, ‏`referenceResponse` ו-`category`. הוסף שלוש שאלות שאין להן תשובה במסמכים שלך.', 'העלה אותו ל-S3 וצור evaluation של Bedrock מסוג "Automatic: Model as a judge" עם Correctness ו-Completeness. קרא את ההסברים של שלושת הציונים הנמוכים ביותר.', 'הרץ את האפליקציה שלך על אותן שאלות, הוסף `modelResponses` לקובץ, והרץ את ה-job שוב עם "Bring your own inference responses".', 'אם יש לך knowledge base: הרץ RAG evaluation מסוג retrieve-only והסתכל על Context relevance ו-Context coverage.', 'אם יש לך סוכן על AgentCore Runtime: הרץ `agentcore add online-eval` עם `Builtin.GoalSuccessRate` ו-`Builtin.Helpfulness`, עשה deploy, שלח כמה שיחות, ומצא את הציונים בלשונית Evaluations ב-CloudWatch.', 'תן ציון לעשר תשובות בעצמך בלי להסתכל על ה-judge, והשווה.', 'עצור או מחק את מה שיצרת, כדי שזה לא ימשיך לעלות כסף.'] } }
      ]
    }
  ]
});
